import { IgcCustomPaletteColorScaleModule } from './igc-custom-palette-color-scale-module';

import { IgcScatterAreaSeriesComponent } from './igc-scatter-area-series-component';
import { ScatterAreaSeries } from './ScatterAreaSeries';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcScatterAreaSeriesModule {
    public static register(): void {
IgcCustomPaletteColorScaleModule.register();
        IgcScatterAreaSeriesComponent.register();
        TypeRegistrar.registerCons("IgcScatterAreaSeriesComponent", IgcScatterAreaSeriesComponent);
        TypeRegistrar.register("ScatterAreaSeries", (<any>ScatterAreaSeries).$type);
    }
}
