import { IgcHorizontalAnchoredCategorySeriesProxyModule } from './igc-horizontal-anchored-category-series-proxy-module';

import { IgcPointSeriesComponent } from './igc-point-series-component';
import { PointSeries } from './PointSeries';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcPointSeriesModule {
    public static register(): void {
IgcHorizontalAnchoredCategorySeriesProxyModule.register();
        IgcPointSeriesComponent.register();
        TypeRegistrar.registerCons("IgcPointSeriesComponent", IgcPointSeriesComponent);
        TypeRegistrar.register("PointSeries", (<any>PointSeries).$type);
    }
}
