import { IgcIndicatorProxyModule } from './igc-indicator-proxy-module';

import { IgcTRIXIndicatorComponent } from './igc-trix-indicator-component';
import { TRIXIndicator } from './TRIXIndicator';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcTRIXIndicatorModule {
    public static register(): void {
IgcIndicatorProxyModule.register();
        IgcTRIXIndicatorComponent.register();
        TypeRegistrar.registerCons("IgcTRIXIndicatorComponent", IgcTRIXIndicatorComponent);
        TypeRegistrar.register("TRIXIndicator", (<any>TRIXIndicator).$type);
    }
}
