import { IgcSizeScaleModule } from './igc-size-scale-module';
import { IgcBrushScaleModule } from './igc-brush-scale-module';
import { IgcValueBrushScaleModule } from './igc-value-brush-scale-module';
import { IgcCustomPaletteBrushScaleModule } from './igc-custom-palette-brush-scale-module';

import { IgcBubbleSeriesComponent } from './igc-bubble-series-component';
import { BubbleSeries } from './BubbleSeries';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcBubbleSeriesModule {
    public static register(): void {
IgcSizeScaleModule.register();
IgcBrushScaleModule.register();
IgcValueBrushScaleModule.register();
IgcCustomPaletteBrushScaleModule.register();
        IgcBubbleSeriesComponent.register();
        TypeRegistrar.registerCons("IgcBubbleSeriesComponent", IgcBubbleSeriesComponent);
        TypeRegistrar.register("BubbleSeries", (<any>BubbleSeries).$type);
    }
}
