import { IgcHorizontalAnchoredCategorySeriesProxyModule } from './igc-horizontal-anchored-category-series-proxy-module';

import { IgcLineSeriesComponent } from './igc-line-series-component';
import { LineSeries } from './LineSeries';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcLineSeriesModule {
    public static register(): void {
IgcHorizontalAnchoredCategorySeriesProxyModule.register();
        IgcLineSeriesComponent.register();
        TypeRegistrar.registerCons("IgcLineSeriesComponent", IgcLineSeriesComponent);
        TypeRegistrar.register("LineSeries", (<any>LineSeries).$type);
    }
}
