import { IgcOverlayProxyModule } from './igc-overlay-proxy-module';

import { IgcPriceChannelOverlayComponent } from './igc-price-channel-overlay-component';
import { PriceChannelOverlay } from './PriceChannelOverlay';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcPriceChannelOverlayModule {
    public static register(): void {
IgcOverlayProxyModule.register();
        IgcPriceChannelOverlayComponent.register();
        TypeRegistrar.registerCons("IgcPriceChannelOverlayComponent", IgcPriceChannelOverlayComponent);
        TypeRegistrar.register("PriceChannelOverlay", (<any>PriceChannelOverlay).$type);
    }
}
