import { Base, ValueType, Type, markType } from "igniteui-core/type";
import { INumberAbbreviator, INumberAbbreviator_$type } from "./INumberAbbreviator";
import { MathUtil } from "igniteui-core/MathUtil";
import { round10N } from "igniteui-core/numberExtended";

/**
 * @hidden 
 */
export class NumberAbbreviator extends Base implements INumberAbbreviator {
	static $t: Type = markType(NumberAbbreviator, 'NumberAbbreviator', (<any>Base).$, [INumberAbbreviator_$type]);
	abbreviate(a: number, b: (item: any, fromAbbreviator: boolean) => any): string {
		let c: number = Math.abs(a);
		let d: string[] = <string[]>[ 'Q', 'T', 'B', 'M', 'K' ];
		let e: number[] = <number[]>[ 1E+15, 1000000000000, 1000000000, 1000000, 1000 ];
		for (let f: number = 0; f < d.length; f++) {
			if (c >= e[f]) {
				if (b != null) {
					let g = b(round10N(a / e[f], 1), true);
					if (g != null) {
						return g.toString() + d[f];
					}
				}
				return MathUtil.t(round10N(a / e[f], 1)).toString() + d[f];
			}
		}
		if (b != null) {
			let h = b(a, false);
			if (h != null) {
				return h.toString();
			}
		}
		return MathUtil.t(a);
	}
}


