import { IgRect } from 'igniteui-core/IgRect'
import { IgSize } from 'igniteui-core/IgSize'
import { IgPoint } from 'igniteui-core/IgPoint'
import { IgDataTemplate } from 'igniteui-core/IgDataTemplate'
import { IgcHTMLElement } from 'igniteui-core/igc-html-element'
import { IgcUserAnnotationInformation } from "./igc-user-annotation-information";
import { UserAnnotationToolTipContentUpdatingEventArgs as UserAnnotationToolTipContentUpdatingEventArgs_internal } from "./UserAnnotationToolTipContentUpdatingEventArgs";

/**
 * Information about the user annotation content which is being created or updated.
*/
export class IgcUserAnnotationToolTipContentUpdatingEventArgs
{

protected createImplementation() : UserAnnotationToolTipContentUpdatingEventArgs_internal
{
	return new UserAnnotationToolTipContentUpdatingEventArgs_internal();
}
	protected _implementation: any;
	                            /**
	                             * @hidden 
	                             */
	public get i() : UserAnnotationToolTipContentUpdatingEventArgs_internal {
		return this._implementation;
	}
	private onImplementationCreated() {
		
	}
	constructor() {
	this._implementation = this.createImplementation();
	(<any>this._implementation).externalObject = this;
	this.onImplementationCreated();
	                                if ((this as any)._initializeAdapters) {
	                                    (this as any)._initializeAdapters();
	                                }
	
	}
	protected _provideImplementation(i: any) {
	    this._implementation = i;
	    (<any>this._implementation).externalObject = this;
	this.onImplementationCreated();
	                                if ((this as any)._initializeAdapters) {
	                                    (this as any)._initializeAdapters();
	                                }
	
	}
	get annotationInfo() : IgcUserAnnotationInformation {
	                                        const r = this.i.annotationInfo;
	                                        if (r == null) {
	                                            return null;
	                                        }
	                                        
	                                        if (!(r as any).externalObject) {
	                                            let e = new IgcUserAnnotationInformation();
	                                            if ((r as any).$type) {
	                                                (e as any)._implementation = r;
	                                            } else {
	                                                if ((e.i as any).setNativeElement) {
	                                                    (e.i as any).setNativeElement(r);
	                                                }
	                                            }
	                                            (r as any).externalObject = e;
	                                        }
		return (r as any).externalObject;
	}
	set annotationInfo(v: IgcUserAnnotationInformation) {
		v == null ? this.i.annotationInfo = null : this.i.annotationInfo = v.i;
	}
	get content() : any {
		return this.i.content as any;
	}
	set content(v: any) {
	                                        this.i.content = v;
	}
}
