import { IgcOverlayProxyModule } from './igc-overlay-proxy-module';

import { IgcBollingerBandsOverlayComponent } from './igc-bollinger-bands-overlay-component';
import { BollingerBandsOverlay } from './BollingerBandsOverlay';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcBollingerBandsOverlayModule {
    public static register(): void {
IgcOverlayProxyModule.register();
        IgcBollingerBandsOverlayComponent.register();
        TypeRegistrar.registerCons("IgcBollingerBandsOverlayComponent", IgcBollingerBandsOverlayComponent);
        TypeRegistrar.register("BollingerBandsOverlay", (<any>BollingerBandsOverlay).$type);
    }
}
