import { HighlightingManager } from "igniteui-core/HighlightingManager";
import { Base, Type, markType } from "igniteui-core/type";
import { Series } from "./Series";
import { SeriesHighlightingMode } from "./SeriesHighlightingMode";

/**
 * @hidden 
 */
export class SeriesHighlightingManager extends HighlightingManager {
	static $t: Type = markType(SeriesHighlightingManager, 'SeriesHighlightingManager', (<any>HighlightingManager).$);
	isCrossContextHighlight(a: any): boolean {
		let b = <Series>a;
		if (b.by == 5 || b.by == 4) {
			return true;
		}
		return false;
	}
	isContextValid(a: any): boolean {
		let b = <Series>a;
		return b != null && b.dc != null;
	}
}


