import { IgcIndicatorProxyModule } from './igc-indicator-proxy-module';

import { IgcTypicalPriceIndicatorComponent } from './igc-typical-price-indicator-component';
import { TypicalPriceIndicator } from './TypicalPriceIndicator';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcTypicalPriceIndicatorModule {
    public static register(): void {
IgcIndicatorProxyModule.register();
        IgcTypicalPriceIndicatorComponent.register();
        TypeRegistrar.registerCons("IgcTypicalPriceIndicatorComponent", IgcTypicalPriceIndicatorComponent);
        TypeRegistrar.register("TypicalPriceIndicator", (<any>TypicalPriceIndicator).$type);
    }
}
