import { IgRect } from 'igniteui-core/IgRect'
import { IgSize } from 'igniteui-core/IgSize'
import { IgPoint } from 'igniteui-core/IgPoint'
import { IgDataTemplate } from 'igniteui-core/IgDataTemplate'
import { IgcHTMLElement } from 'igniteui-core/igc-html-element'
import { IgcUserStripAnnotation } from "./igc-user-strip-annotation";
import { UserStripAnnotationStylingEventArgs as UserStripAnnotationStylingEventArgs_internal } from "./UserStripAnnotationStylingEventArgs";

/**
 * Represents the event arguments for the UserAxisAnnotation styling events.
*/
export class IgcUserStripAnnotationStylingEventArgs
{

protected createImplementation() : UserStripAnnotationStylingEventArgs_internal
{
	return new UserStripAnnotationStylingEventArgs_internal();
}
	protected _implementation: any;
	                            /**
	                             * @hidden 
	                             */
	public get i() : UserStripAnnotationStylingEventArgs_internal {
		return this._implementation;
	}
	private onImplementationCreated() {
		
	}
	constructor() {
	this._implementation = this.createImplementation();
	(<any>this._implementation).externalObject = this;
	this.onImplementationCreated();
	                                if ((this as any)._initializeAdapters) {
	                                    (this as any)._initializeAdapters();
	                                }
	
	}
	protected _provideImplementation(i: any) {
	    this._implementation = i;
	    (<any>this._implementation).externalObject = this;
	this.onImplementationCreated();
	                                if ((this as any)._initializeAdapters) {
	                                    (this as any)._initializeAdapters();
	                                }
	
	}
	/**
	 * The annotation to style.
	*/
	get annotation() : IgcUserStripAnnotation {
	                                        const r = this.i.annotation;
	                                        if (r == null) {
	                                            return null;
	                                        }
	                                        
	                                        if (!(r as any).externalObject) {
	                                            let e = new IgcUserStripAnnotation();
	                                            if ((r as any).$type) {
	                                                (e as any)._implementation = r;
	                                            } else {
	                                                if ((e.i as any).setNativeElement) {
	                                                    (e.i as any).setNativeElement(r);
	                                                }
	                                            }
	                                            (r as any).externalObject = e;
	                                        }
		return (r as any).externalObject;
	}
	set annotation(v: IgcUserStripAnnotation) {
		v == null ? this.i.annotation = null : this.i.annotation = v.i;
	}
}
