import { IgRect } from 'igniteui-core/IgRect'
import { IgSize } from 'igniteui-core/IgSize'
import { IgPoint } from 'igniteui-core/IgPoint'
import { IgDataTemplate } from 'igniteui-core/IgDataTemplate'
import { IgcHTMLElement } from 'igniteui-core/igc-html-element'
import { IgcSeriesComponent } from "./igc-series-component";
import { IgcSeriesMatcher } from "./igc-series-matcher";
import { IgcUserBaseAnnotation } from "./igc-user-base-annotation";
import { UserPointAnnotation as UserPointAnnotation_internal } from "./UserPointAnnotation";

/**
 * Represents an user annotation for rendering data point annotation on a series
*/
export class IgcUserPointAnnotation extends IgcUserBaseAnnotation
{

protected createImplementation() : UserPointAnnotation_internal
{
	return new UserPointAnnotation_internal();
}
	/**
	                             * @hidden 
	                             */
	                            public get i() : UserPointAnnotation_internal {
		return this._implementation;
	}
	constructor() {
		super();
	}
	/**
	 * Gets or sets the target series that will display the annotation.
	*/
	get targetSeries() : IgcSeriesComponent {
	                                        const r = this.i.targetSeries;
	                                        if (r == null) {
	                                            return null;
	                                        }
	                                        
	                                        if (!(r as any).externalObject) {
	                                            let e = IgcSeriesComponent._createFromInternal(r);
	                                            if (e) {
	                                                (e as any)._implementation = r;
	                                            }
	                                            (r as any).externalObject = e;
	                                        }
		return (r as any).externalObject;
	}
	set targetSeries(v: IgcSeriesComponent) {
		v == null ? this.i.targetSeries = null : this.i.targetSeries = v.i;
	}
	
	            private _targetSeriesName: string = null;
	            /**
	            * Gets or sets the name to use to resolve targetSeries from markup.
	            */
	            public get targetSeriesName(): string {
	                return this._targetSeriesName;
	            }
	            public set targetSeriesName(v: string) {
	                this._targetSeriesName = v;                
	            }
	/**
	 * Gets or sets a matcher for matching a series that will display the annotation.
	*/
	get targetSeriesMatcher() : IgcSeriesMatcher {
	                                        const r = this.i.targetSeriesMatcher;
	                                        if (r == null) {
	                                            return null;
	                                        }
	                                        
	                                        if (!(r as any).externalObject) {
	                                            let e = new IgcSeriesMatcher();
	                                            if ((r as any).$type) {
	                                                (e as any)._implementation = r;
	                                            } else {
	                                                if ((e.i as any).setNativeElement) {
	                                                    (e.i as any).setNativeElement(r);
	                                                }
	                                            }
	                                            (r as any).externalObject = e;
	                                        }
		return (r as any).externalObject;
	}
	set targetSeriesMatcher(v: IgcSeriesMatcher) {
		v == null ? this.i.targetSeriesMatcher = null : this.i.targetSeriesMatcher = v.i;
	}
	/**
	 * Gets or sets the value that determines location of the annotation in the coordinates of x-axis.
	*/
	get xValue() : number {
		return (this.i.xValue as number);
	}
	set xValue(v: number) {
		this.i.xValue = +v;
	}
	/**
	 * Gets or sets the value that determines location of the annotation in the coordinates of y-axis.
	*/
	get yValue() : number {
		return (this.i.yValue as number);
	}
	set yValue(v: number) {
		this.i.yValue = +v;
	}
	
	             public bindSeries(series: IgcSeriesComponent[]) {
	                super.bindSeries(series);
	                	
	            for (let i = 0; i < series.length; i++) {
	                if (this.targetSeriesName && this.targetSeriesName.length > 0 &&
	                    series[i].name == this.targetSeriesName) {
	                    this.targetSeries = series[i] as IgcSeriesComponent;
	                }
	            }
	
	}
	
	    public findByName(name: string): any {
	        
	    var baseResult = super.findByName(name);
	    if (baseResult)
	    {
	        return baseResult;
	    }
	
	if (this.targetSeries && (this.targetSeries as any).name && (this.targetSeries as any).name == name) { return this.targetSeries; }
	if (this.targetSeriesMatcher && (this.targetSeriesMatcher as any).name && (this.targetSeriesMatcher as any).name == name) { return this.targetSeriesMatcher; }
	
	        return null;
	    }
}
