import { IgcTimeAxisBreakComponent } from './igc-time-axis-break-component';
import { TimeAxisBreak } from './TimeAxisBreak';
import { TypeRegistrar } from 'igniteui-core/type';
import { IgcTimeAxisBreakCollection } from './igc-time-axis-break-collection';
import { TimeAxisBreakCollection } from './TimeAxisBreakCollection';


export class IgcTimeAxisBreakModule {
    public static register(): void {
        IgcTimeAxisBreakComponent.register();
        TypeRegistrar.registerCons("IgcTimeAxisBreakComponent", IgcTimeAxisBreakComponent);
        TypeRegistrar.register("TimeAxisBreak", (<any>TimeAxisBreak).$type);
        TypeRegistrar.registerCons("IgcTimeAxisBreakCollection", IgcTimeAxisBreakCollection);
        TypeRegistrar.register("TimeAxisBreakCollection", (<any>TimeAxisBreakCollection).$type);     

    }
}
