import { IgcIndicatorProxyModule } from './igc-indicator-proxy-module';

import { IgcPositiveVolumeIndexIndicatorComponent } from './igc-positive-volume-index-indicator-component';
import { PositiveVolumeIndexIndicator } from './PositiveVolumeIndexIndicator';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcPositiveVolumeIndexIndicatorModule {
    public static register(): void {
IgcIndicatorProxyModule.register();
        IgcPositiveVolumeIndexIndicatorComponent.register();
        TypeRegistrar.registerCons("IgcPositiveVolumeIndexIndicatorComponent", IgcPositiveVolumeIndexIndicatorComponent);
        TypeRegistrar.register("PositiveVolumeIndexIndicator", (<any>PositiveVolumeIndexIndicator).$type);
    }
}
