import { ListSortDirection, ListSortDirection_$type } from "igniteui-core/ListSortDirection";
import { ChartSortDescription } from "./ChartSortDescription";
import { ensureEnum } from "igniteui-core/componentUtil";

/**
 * Represents an element in the current sort applied to a data source or provider. Changes to this object are not observed or expected after it is initially assigned to a collection.
*/
export class IgcChartSortDescription {

	protected createImplementation(): ChartSortDescription {
		return new ChartSortDescription(0);
	}
	protected _implementation: any;
	/**
	 * @hidden 
	 */
	public get i(): ChartSortDescription {
		return this._implementation;
	}
	private onImplementationCreated() {

	}
	constructor(field: string = null, sortDirection: ListSortDirection = ListSortDirection.Ascending) {
		this._implementation = this.createImplementation();
		(this._implementation as any).externalObject = this;
		this.onImplementationCreated();

		this.field = field;
		this.sortDirection = sortDirection;
	}
	protected _provideImplementation(i: any) {
		this._implementation = i;
		(this._implementation as any).externalObject = this;
		this.onImplementationCreated();
	}

		/**
	 * Gets or sets the property being sorted.
	*/
	get field() : string {
		return (this.i.f as string);
	}
	set field(v: string) {
		this.i.f = v;
	}
	/**
	 * Gets or sets the direction to sort based on the property.
	*/
	get sortDirection() : ListSortDirection {
		return this.i.c;
	}
	set sortDirection(v: ListSortDirection) {
		this.i.c = ensureEnum<ListSortDirection>(ListSortDirection_$type, v);
	}

    	
	    public findByName(name: string): any {
	        
	    if ((this as any).findEphemera) {
	        if (name && name.indexOf("@@e:") == 0) {
	            return (this as any).findEphemera(name);
	        }
	    }
	
	
	        return null;
	    }

    

		/**
	 * Returns if the SortDescription is equal to another.
	
	* @param other  * The SortDescription to compare to.
	*/
	public equals(other: any) : boolean {
	                        
		let iv = this.i.equals(other);
	                        return (iv);
	}

    
}
