import { IgcIndicatorProxyModule } from './igc-indicator-proxy-module';

import { IgcPercentageVolumeOscillatorIndicatorComponent } from './igc-percentage-volume-oscillator-indicator-component';
import { PercentageVolumeOscillatorIndicator } from './PercentageVolumeOscillatorIndicator';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcPercentageVolumeOscillatorIndicatorModule {
    public static register(): void {
IgcIndicatorProxyModule.register();
        IgcPercentageVolumeOscillatorIndicatorComponent.register();
        TypeRegistrar.registerCons("IgcPercentageVolumeOscillatorIndicatorComponent", IgcPercentageVolumeOscillatorIndicatorComponent);
        TypeRegistrar.register("PercentageVolumeOscillatorIndicator", (<any>PercentageVolumeOscillatorIndicator).$type);
    }
}
