import { IgcIndicatorProxyModule } from './igc-indicator-proxy-module';

import { IgcBollingerBandWidthIndicatorComponent } from './igc-bollinger-band-width-indicator-component';
import { BollingerBandWidthIndicator } from './BollingerBandWidthIndicator';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcBollingerBandWidthIndicatorModule {
    public static register(): void {
IgcIndicatorProxyModule.register();
        IgcBollingerBandWidthIndicatorComponent.register();
        TypeRegistrar.registerCons("IgcBollingerBandWidthIndicatorComponent", IgcBollingerBandWidthIndicatorComponent);
        TypeRegistrar.register("BollingerBandWidthIndicator", (<any>BollingerBandWidthIndicator).$type);
    }
}
