import { IgcIndicatorProxyModule } from './igc-indicator-proxy-module';

import { IgcChaikinVolatilityIndicatorComponent } from './igc-chaikin-volatility-indicator-component';
import { ChaikinVolatilityIndicator } from './ChaikinVolatilityIndicator';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcChaikinVolatilityIndicatorModule {
    public static register(): void {
IgcIndicatorProxyModule.register();
        IgcChaikinVolatilityIndicatorComponent.register();
        TypeRegistrar.registerCons("IgcChaikinVolatilityIndicatorComponent", IgcChaikinVolatilityIndicatorComponent);
        TypeRegistrar.register("ChaikinVolatilityIndicator", (<any>ChaikinVolatilityIndicator).$type);
    }
}
