import { IgcIndicatorProxyModule } from './igc-indicator-proxy-module';

import { IgcSlowStochasticOscillatorIndicatorComponent } from './igc-slow-stochastic-oscillator-indicator-component';
import { SlowStochasticOscillatorIndicator } from './SlowStochasticOscillatorIndicator';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcSlowStochasticOscillatorIndicatorModule {
    public static register(): void {
IgcIndicatorProxyModule.register();
        IgcSlowStochasticOscillatorIndicatorComponent.register();
        TypeRegistrar.registerCons("IgcSlowStochasticOscillatorIndicatorComponent", IgcSlowStochasticOscillatorIndicatorComponent);
        TypeRegistrar.register("SlowStochasticOscillatorIndicator", (<any>SlowStochasticOscillatorIndicator).$type);
    }
}
