import { RenderingMessage } from "./RenderingMessage";
import { Base, Type, markType } from "igniteui-core/type";

/**
 * @hidden 
 */
export class TooltipValueChangedMessage extends RenderingMessage {
	static $t: Type = markType(TooltipValueChangedMessage, 'TooltipValueChangedMessage', (<any>RenderingMessage).$);
	private f: any = null;
	get g(): any {
		return this.f;
	}
	set g(a: any) {
		this.f = a;
	}
	toString(): string {
		return "TooltipValueChangedMessage[" + this.g.toString() + "]";
	}
}


