import { IgcIndicatorProxyModule } from './igc-indicator-proxy-module';

import { IgcPriceVolumeTrendIndicatorComponent } from './igc-price-volume-trend-indicator-component';
import { PriceVolumeTrendIndicator } from './PriceVolumeTrendIndicator';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcPriceVolumeTrendIndicatorModule {
    public static register(): void {
IgcIndicatorProxyModule.register();
        IgcPriceVolumeTrendIndicatorComponent.register();
        TypeRegistrar.registerCons("IgcPriceVolumeTrendIndicatorComponent", IgcPriceVolumeTrendIndicatorComponent);
        TypeRegistrar.register("PriceVolumeTrendIndicator", (<any>PriceVolumeTrendIndicator).$type);
    }
}
