    private createTooltip(): any {
        if (!TypeRegistrar.isRegistered("IgcTooltipContainerComponent")) {
            return null;
        }
        let cr = TypeRegistrar.create("IgcTooltipContainerComponent");
        let ele: Element = cr;
        let self = this;

        (<any>ele).updateToolTip = function (c) {
            if (c.externalObject) {
                c = c.externalObject;
            } else {
                let ext = new IgcDataContext();
                (<any>ext)._implementation = c;
                c = ext;
            }

            if (ele.parentElement != self._container.getNativeElement()) {
                if (ele.parentElement != null) {
                    ele.parentElement.removeChild(ele);
                }

                self._container.append(this._renderer.createWrapper(ele));
            }
            (<any>cr).context = c;
            (<any>ele).style.display = "block";

            return true;
        };
        (<any>ele).hideToolTip = function () {
            (<any>ele).style.display = "none"
        };
        (<any>ele).style.display = "none"

        return cr;
    }

