import { IgcCustomContourValueResolverComponent } from './igc-custom-contour-value-resolver-component';
import { CustomContourValueResolver } from './CustomContourValueResolver';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcCustomContourValueResolverModule {
    public static register(): void {
        IgcCustomContourValueResolverComponent.register();
        TypeRegistrar.registerCons("IgcCustomContourValueResolverComponent", IgcCustomContourValueResolverComponent);
        TypeRegistrar.register("CustomContourValueResolver", (<any>CustomContourValueResolver).$type);
    }
}
