import { IgcAnnotationLayerProxyModule } from './igc-annotation-layer-proxy-module';

import { IgcCalloutLayerComponent } from './igc-callout-layer-component';
import { CalloutLayer } from './CalloutLayer';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcCalloutLayerModule {
    public static register(): void {
IgcAnnotationLayerProxyModule.register();
        IgcCalloutLayerComponent.register();
        TypeRegistrar.registerCons("IgcCalloutLayerComponent", IgcCalloutLayerComponent);
        TypeRegistrar.register("CalloutLayer", (<any>CalloutLayer).$type);
    }
}
