import { IgcIndicatorProxyModule } from './igc-indicator-proxy-module';

import { IgcMassIndexIndicatorComponent } from './igc-mass-index-indicator-component';
import { MassIndexIndicator } from './MassIndexIndicator';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcMassIndexIndicatorModule {
    public static register(): void {
IgcIndicatorProxyModule.register();
        IgcMassIndexIndicatorComponent.register();
        TypeRegistrar.registerCons("IgcMassIndexIndicatorComponent", IgcMassIndexIndicatorComponent);
        TypeRegistrar.register("MassIndexIndicator", (<any>MassIndexIndicator).$type);
    }
}
