import { Base, Type, markType } from "igniteui-core/type";
import { truncate, log10 } from "igniteui-core/number";

/**
 * @hidden 
 */
export class Snapper extends Base {
	static $t: Type = markType(Snapper, 'Snapper');
	private c: number = 7;
	protected get f(): number {
		return this.c;
	}
	protected set f(a: number) {
		this.c = a;
	}
	private a: boolean = false;
	protected get b(): boolean {
		return this.a;
	}
	protected set b(a: boolean) {
		this.a = a;
	}
	protected static d(a: number, b: number): number {
		let c: number = 1;
		if (b > 0) {
			for (; b > 0; --b) {
				c *= a;
			}
		} else {
			for (; b < 0; ++b) {
				c /= a;
			}
		}
		return c;
	}
	protected static e(a: number, b: boolean): number {
		let c: number = <number>truncate(Math.floor(log10(a)));
		let d: number = a / Math.pow(10, c);
		if (b) {
			let e: number = d < 1.5 ? 1 : d < 3 ? 2 : d < 7 ? 5 : 10;
			return e * Math.pow(10, c);
		} else {
			let f: number = d <= 1 ? 1 : d <= 2 ? 2 : d <= 5 ? 5 : 10;
			return f * Math.pow(10, c);
		}
	}
}


