import { IgcIndicatorProxyModule } from './igc-indicator-proxy-module';

import { IgcCommodityChannelIndexIndicatorComponent } from './igc-commodity-channel-index-indicator-component';
import { CommodityChannelIndexIndicator } from './CommodityChannelIndexIndicator';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcCommodityChannelIndexIndicatorModule {
    public static register(): void {
IgcIndicatorProxyModule.register();
        IgcCommodityChannelIndexIndicatorComponent.register();
        TypeRegistrar.registerCons("IgcCommodityChannelIndexIndicatorComponent", IgcCommodityChannelIndexIndicatorComponent);
        TypeRegistrar.register("CommodityChannelIndexIndicator", (<any>CommodityChannelIndexIndicator).$type);
    }
}
