import { IgcIndicatorProxyModule } from './igc-indicator-proxy-module';

import { IgcRelativeStrengthIndexIndicatorComponent } from './igc-relative-strength-index-indicator-component';
import { RelativeStrengthIndexIndicator } from './RelativeStrengthIndexIndicator';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcRelativeStrengthIndexIndicatorModule {
    public static register(): void {
IgcIndicatorProxyModule.register();
        IgcRelativeStrengthIndexIndicatorComponent.register();
        TypeRegistrar.registerCons("IgcRelativeStrengthIndexIndicatorComponent", IgcRelativeStrengthIndexIndicatorComponent);
        TypeRegistrar.register("RelativeStrengthIndexIndicator", (<any>RelativeStrengthIndexIndicator).$type);
    }
}
