import { IgRect } from 'igniteui-core/IgRect'
import { IgSize } from 'igniteui-core/IgSize'
import { IgPoint } from 'igniteui-core/IgPoint'
import { IgDataTemplate } from 'igniteui-core/IgDataTemplate'
import { IgcHTMLElement } from 'igniteui-core/igc-html-element'
import { IgcTimeAxisLabelFormatComponent } from "./igc-time-axis-label-format-component";
import { LabelFormatOverrideEventArgs as LabelFormatOverrideEventArgs_internal } from "./LabelFormatOverrideEventArgs";

/**
 * Event args used byt the LabelFormatOverride Delegate to provide a way to override default label functionality..
*/
export class IgcLabelFormatOverrideEventArgs
{

protected createImplementation() : LabelFormatOverrideEventArgs_internal
{
	return new LabelFormatOverrideEventArgs_internal();
}
	protected _implementation: any;
	                            /**
	                             * @hidden 
	                             */
	public get i() : LabelFormatOverrideEventArgs_internal {
		return this._implementation;
	}
	private onImplementationCreated() {
		
	}
	constructor() {
	this._implementation = this.createImplementation();
	(<any>this._implementation).externalObject = this;
	this.onImplementationCreated();
	                                if ((this as any)._initializeAdapters) {
	                                    (this as any)._initializeAdapters();
	                                }
	
	}
	protected _provideImplementation(i: any) {
	    this._implementation = i;
	    (<any>this._implementation).externalObject = this;
	this.onImplementationCreated();
	                                if ((this as any)._initializeAdapters) {
	                                    (this as any)._initializeAdapters();
	                                }
	
	}
	/**
	 * The DateTime the override is invoked with.
	*/
	get dateTime() : Date {
		return (this.i.dateTime as Date);
	}
	set dateTime(v: Date) {
		this.i.dateTime = v;
	}
	/**
	 * The format to which this override is attached.
	*/
	get format() : IgcTimeAxisLabelFormatComponent {
	                                        const r = this.i.format;
	                                        if (r == null) {
	                                            return null;
	                                        }
	                                        
	                                        if (!(r as any).externalObject) {
	                                            let e = IgcTimeAxisLabelFormatComponent._createFromInternal(r);
	                                            if (e) {
	                                                (e as any)._implementation = r;
	                                            }
	                                            (r as any).externalObject = e;
	                                        }
		return (r as any).externalObject;
	}
	set format(v: IgcTimeAxisLabelFormatComponent) {
		v == null ? this.i.format = null : this.i.format = v.i;
	}
	/**
	 * Gets or sets the label that should be used.
	*/
	get label() : string {
		return (this.i.label as string);
	}
	set label(v: string) {
		this.i.label = v;
	}
}
