import { RenderingMessage } from "./RenderingMessage";
import { Point, Base, Type, markType } from "igniteui-core/type";

/**
 * @hidden 
 */
export class TooltipUpdateMessage extends RenderingMessage {
	static $t: Type = markType(TooltipUpdateMessage, 'TooltipUpdateMessage', (<any>RenderingMessage).$);
	private h: Point = null;
	get i(): Point {
		return this.h;
	}
	set i(a: Point) {
		this.h = a;
	}
	private f: any = null;
	get g(): any {
		return this.f;
	}
	set g(a: any) {
		this.f = a;
	}
	toString(): string {
		return "TooltipUpdateMessage[" + this.i.toString() + ", " + this.g.toString() + "]";
	}
}


