/**
 * Represents an annotation layer that renders bands (line with breadth) at locations of x/y values mapped to these properties:
 * StartValueXMemberPath 
 * StartValueYMemberPath 
 * EndValueXMemberPath 
 * EndValueYMemberPath 
 * AnnotationBreadthMemberPath
*/
export class IgcDataAnnotationBandLayerComponent extends IgcDataAnnotationPointLayerComponent
{

protected createImplementation() : DataAnnotationBandLayer
{
	return new DataAnnotationBandLayer();
}
	/**
	                             * @hidden 
	                             */
	                            public get i() : DataAnnotationBandLayer {
		return this._implementation;
	}
	constructor() {
		super()
	                                     
	}
	
	    connectedCallback() {
	        if (super["connectedCallback"]) {
	            super["connectedCallback"]();
	        }
	        if ((<any>this.i).connectedCallback) {
	            (<any>this.i).connectedCallback();
	        }
	        
	        if (!this._attached) {
	            this._attached = true;
	            this._flushQueuedAttributes();
	        }
	    }
	    disconnectedCallback() {
	        if (super["disconnectedCallback"]) {
	            super["disconnectedCallback"]();
	        }
	        if ((<any>this.i).disconnectedCallback) {
	            (<any>this.i).disconnectedCallback();
	        }
	        if (this._attached) {
	            this._attached = false;
	        }
	    }
	
	                private static _observedAttributesIgcDataAnnotationBandLayerComponent: string[] = null;
	                static get observedAttributes() {
	                    if (IgcDataAnnotationBandLayerComponent._observedAttributesIgcDataAnnotationBandLayerComponent == null) {
	                        let names = getAllPropertyNames(IgcDataAnnotationBandLayerComponent);
	    for (let i = 0; i < names.length; i++) {
	                            names[i] = toSpinal(names[i]);
	    }
	    IgcDataAnnotationBandLayerComponent._observedAttributesIgcDataAnnotationBandLayerComponent = names;
	                    }
	                    return IgcDataAnnotationBandLayerComponent._observedAttributesIgcDataAnnotationBandLayerComponent;               
	                }                 
	            
	
	                public static htmlTagName: string = "igc-data-annotation-band-layer";
	                protected static _isElementRegistered = false;
	
	                public static register() {
	                    if (!IgcDataAnnotationBandLayerComponent._isElementRegistered) {
	                        IgcDataAnnotationBandLayerComponent._isElementRegistered = true;
	                        RegisterElementHelper.registerElement(
	                            IgcDataAnnotationBandLayerComponent.htmlTagName,
	                            IgcDataAnnotationBandLayerComponent);
	                    }
	            }
	/**
	 * Gets or sets name of data column with breath/size of shape annotations.
	*/
	get annotationBreadthMemberPath() : string {
		return (this.i.ak9 as string);
	}
	set annotationBreadthMemberPath(v: string) {
		this.i.ak9 = v;
	}
}
