import { IgcAnnotationLayerProxyModule } from './igc-annotation-layer-proxy-module';

import { IgcCrosshairLayerComponent } from './igc-crosshair-layer-component';
import { CrosshairLayer } from './CrosshairLayer';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcCrosshairLayerModule {
    public static register(): void {
IgcAnnotationLayerProxyModule.register();
        IgcCrosshairLayerComponent.register();
        TypeRegistrar.registerCons("IgcCrosshairLayerComponent", IgcCrosshairLayerComponent);
        TypeRegistrar.register("CrosshairLayer", (<any>CrosshairLayer).$type);
    }
}
