import { IgcIndicatorProxyModule } from './igc-indicator-proxy-module';

import { IgcMedianPriceIndicatorComponent } from './igc-median-price-indicator-component';
import { MedianPriceIndicator } from './MedianPriceIndicator';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcMedianPriceIndicatorModule {
    public static register(): void {
IgcIndicatorProxyModule.register();
        IgcMedianPriceIndicatorComponent.register();
        TypeRegistrar.registerCons("IgcMedianPriceIndicatorComponent", IgcMedianPriceIndicatorComponent);
        TypeRegistrar.register("MedianPriceIndicator", (<any>MedianPriceIndicator).$type);
    }
}
