import { DataContext } from "igniteui-core/DataContext";
import { Brush } from "igniteui-core/Brush";
import { Base, Type, markType } from "igniteui-core/type";

/**
 * @hidden 
 */
export class FunnelSliceDataContext extends DataContext {
	static $t: Type = markType(FunnelSliceDataContext, 'FunnelSliceDataContext', (<any>DataContext).$);
	private _itemOutline: Brush = null;
	get itemOutline(): Brush {
		return this._itemOutline;
	}
	set itemOutline(a: Brush) {
		this._itemOutline = a;
	}
	flatten(): any {
		let ret_ = super.flatten();
		let itemOutline_ = this.itemOutline;
		ret_.itemOutline = itemOutline_;
		return ret_;
	}
}


