import { IgcIndicatorProxyModule } from './igc-indicator-proxy-module';

import { IgcAccumulationDistributionIndicatorComponent } from './igc-accumulation-distribution-indicator-component';
import { AccumulationDistributionIndicator } from './AccumulationDistributionIndicator';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcAccumulationDistributionIndicatorModule {
    public static register(): void {
IgcIndicatorProxyModule.register();
        IgcAccumulationDistributionIndicatorComponent.register();
        TypeRegistrar.registerCons("IgcAccumulationDistributionIndicatorComponent", IgcAccumulationDistributionIndicatorComponent);
        TypeRegistrar.register("AccumulationDistributionIndicator", (<any>AccumulationDistributionIndicator).$type);
    }
}
