import { IgcIndicatorProxyModule } from './igc-indicator-proxy-module';

import { IgcFastStochasticOscillatorIndicatorComponent } from './igc-fast-stochastic-oscillator-indicator-component';
import { FastStochasticOscillatorIndicator } from './FastStochasticOscillatorIndicator';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcFastStochasticOscillatorIndicatorModule {
    public static register(): void {
IgcIndicatorProxyModule.register();
        IgcFastStochasticOscillatorIndicatorComponent.register();
        TypeRegistrar.registerCons("IgcFastStochasticOscillatorIndicatorComponent", IgcFastStochasticOscillatorIndicatorComponent);
        TypeRegistrar.register("FastStochasticOscillatorIndicator", (<any>FastStochasticOscillatorIndicator).$type);
    }
}
