import { IgcAnnotationLayerProxyModule } from './igc-annotation-layer-proxy-module';

import { IgcCategoryItemHighlightLayerComponent } from './igc-category-item-highlight-layer-component';
import { CategoryItemHighlightLayer } from './CategoryItemHighlightLayer';
