import { IgcIndicatorProxyModule } from './igc-indicator-proxy-module';

import { IgcAbsoluteVolumeOscillatorIndicatorComponent } from './igc-absolute-volume-oscillator-indicator-component';
import { AbsoluteVolumeOscillatorIndicator } from './AbsoluteVolumeOscillatorIndicator';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcAbsoluteVolumeOscillatorIndicatorModule {
    public static register(): void {
IgcIndicatorProxyModule.register();
        IgcAbsoluteVolumeOscillatorIndicatorComponent.register();
        TypeRegistrar.registerCons("IgcAbsoluteVolumeOscillatorIndicatorComponent", IgcAbsoluteVolumeOscillatorIndicatorComponent);
        TypeRegistrar.register("AbsoluteVolumeOscillatorIndicator", (<any>AbsoluteVolumeOscillatorIndicator).$type);
    }
}
