import { IgcIndicatorProxyModule } from './igc-indicator-proxy-module';

import { IgcCustomIndicatorComponent } from './igc-custom-indicator-component';
import { CustomIndicator } from './CustomIndicator';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcCustomIndicatorModule {
    public static register(): void {
IgcIndicatorProxyModule.register();
        IgcCustomIndicatorComponent.register();
        TypeRegistrar.registerCons("IgcCustomIndicatorComponent", IgcCustomIndicatorComponent);
        TypeRegistrar.register("CustomIndicator", (<any>CustomIndicator).$type);
    }
}
