import { IgcIndicatorProxyModule } from './igc-indicator-proxy-module';

import { IgcFullStochasticOscillatorIndicatorComponent } from './igc-full-stochastic-oscillator-indicator-component';
import { FullStochasticOscillatorIndicator } from './FullStochasticOscillatorIndicator';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcFullStochasticOscillatorIndicatorModule {
    public static register(): void {
IgcIndicatorProxyModule.register();
        IgcFullStochasticOscillatorIndicatorComponent.register();
        TypeRegistrar.registerCons("IgcFullStochasticOscillatorIndicatorComponent", IgcFullStochasticOscillatorIndicatorComponent);
        TypeRegistrar.register("FullStochasticOscillatorIndicator", (<any>FullStochasticOscillatorIndicator).$type);
    }
}
