import { IgcAnnotationLayerProxyModule } from './igc-annotation-layer-proxy-module';

import { IgcTrendLineLayerComponent } from './igc-trend-line-layer-component';
import { TrendLineLayer } from './TrendLineLayer';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcTrendLineLayerModule {
    public static register(): void {
IgcAnnotationLayerProxyModule.register();
        IgcTrendLineLayerComponent.register();
        TypeRegistrar.registerCons("IgcTrendLineLayerComponent", IgcTrendLineLayerComponent);
        TypeRegistrar.register("TrendLineLayer", (<any>TrendLineLayer).$type);
    }
}
