import { IgcTimeAxisBreakModule } from './igc-time-axis-break-module';
import { IgcTimeAxisIntervalModule } from './igc-time-axis-interval-module';
import { IgcTimeAxisLabelFormatModule } from './igc-time-axis-label-format-module';

import { IgcTimeXAxisComponent } from './igc-time-x-axis-component';
import { TimeXAxis } from './TimeXAxis';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcTimeXAxisModule {
    public static register(): void {
IgcTimeAxisBreakModule.register();
IgcTimeAxisIntervalModule.register();
IgcTimeAxisLabelFormatModule.register();
        IgcTimeXAxisComponent.register();
        TypeRegistrar.registerCons("IgcTimeXAxisComponent", IgcTimeXAxisComponent);
        TypeRegistrar.register("TimeXAxis", (<any>TimeXAxis).$type);
    }
}
