import { IgcIndicatorProxyModule } from './igc-indicator-proxy-module';

import { IgcPercentagePriceOscillatorIndicatorComponent } from './igc-percentage-price-oscillator-indicator-component';
import { PercentagePriceOscillatorIndicator } from './PercentagePriceOscillatorIndicator';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcPercentagePriceOscillatorIndicatorModule {
    public static register(): void {
IgcIndicatorProxyModule.register();
        IgcPercentagePriceOscillatorIndicatorComponent.register();
        TypeRegistrar.registerCons("IgcPercentagePriceOscillatorIndicatorComponent", IgcPercentagePriceOscillatorIndicatorComponent);
        TypeRegistrar.register("PercentagePriceOscillatorIndicator", (<any>PercentagePriceOscillatorIndicator).$type);
    }
}
