import { IgcIndicatorProxyModule } from './igc-indicator-proxy-module';

import { IgcUltimateOscillatorIndicatorComponent } from './igc-ultimate-oscillator-indicator-component';
import { UltimateOscillatorIndicator } from './UltimateOscillatorIndicator';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcUltimateOscillatorIndicatorModule {
    public static register(): void {
IgcIndicatorProxyModule.register();
        IgcUltimateOscillatorIndicatorComponent.register();
        TypeRegistrar.registerCons("IgcUltimateOscillatorIndicatorComponent", IgcUltimateOscillatorIndicatorComponent);
        TypeRegistrar.register("UltimateOscillatorIndicator", (<any>UltimateOscillatorIndicator).$type);
    }
}
