import { IgRect } from 'igniteui-core/IgRect'
import { IgSize } from 'igniteui-core/IgSize'
import { IgPoint } from 'igniteui-core/IgPoint'
import { IgDataTemplate } from 'igniteui-core/IgDataTemplate'
import { IgcHTMLElement } from 'igniteui-core/igc-html-element'
import { IgcCategoryAxisBaseComponent } from "./igc-category-axis-base-component";
import { IgcAnnotationLayerComponent } from "./igc-annotation-layer-component";
import { IgcSeriesComponent } from "./igc-series-component";
import { CategoryHighlightLayer } from "./CategoryHighlightLayer";
import { getAllPropertyNames, fromSpinal, toSpinal, ensureBool } from "igniteui-core/componentUtil";
import { RegisterElementHelper } from "igniteui-core/module-manager";
import { IgcAxisComponent } from "./igc-axis-component";

/**
 * Represents an annotation layer that targets a category axis, or all category axes in the chart. 
 * If the axis contains any series that are aligned between major gridlines of the axis (column, waterfall, etc) this will render a shape that fills the current category. 
 * Otherwise it will render a band with an adjustable thickness at the closest gridline to the pointer position.
 * Setting UseIterpolation to true will cause the x position in the latter case to become affixed to the x position of the pointer.
*/
export class IgcCategoryHighlightLayerComponent extends IgcAnnotationLayerComponent
{

protected createImplementation() : CategoryHighlightLayer
{
	return new CategoryHighlightLayer();
}
	/**
	                             * @hidden 
	                             */
	                            public get i() : CategoryHighlightLayer {
		return this._implementation;
	}
	constructor() {
		super()
	                                     
	}
	
	    connectedCallback() {
	        if (super["connectedCallback"]) {
	            super["connectedCallback"]();
	        }
	        if ((<any>this.i).connectedCallback) {
	            (<any>this.i).connectedCallback();
	        }
	        
	        if (!this._attached) {
	            this._attached = true;
	            this._flushQueuedAttributes();
	        }
	    }
	    disconnectedCallback() {
	        if (super["disconnectedCallback"]) {
	            super["disconnectedCallback"]();
	        }
	        if ((<any>this.i).disconnectedCallback) {
	            (<any>this.i).disconnectedCallback();
	        }
	        if (this._attached) {
	            this._attached = false;
	        }
	    }
	
	                private static _observedAttributesIgcCategoryHighlightLayerComponent: string[] = null;
	                static get observedAttributes() {
	                    if (IgcCategoryHighlightLayerComponent._observedAttributesIgcCategoryHighlightLayerComponent == null) {
	                        let names = getAllPropertyNames(IgcCategoryHighlightLayerComponent);
	    for (let i = 0; i < names.length; i++) {
	                            names[i] = toSpinal(names[i]);
	    }
	    IgcCategoryHighlightLayerComponent._observedAttributesIgcCategoryHighlightLayerComponent = names;
	                    }
	                    return IgcCategoryHighlightLayerComponent._observedAttributesIgcCategoryHighlightLayerComponent;               
	                }                 
	            
	
	                public static htmlTagName: string = "igc-category-highlight-layer";
	                protected static _isElementRegistered = false;
	
	                public static register() {
	                    if (!IgcCategoryHighlightLayerComponent._isElementRegistered) {
	                        IgcCategoryHighlightLayerComponent._isElementRegistered = true;
	                        RegisterElementHelper.registerElement(
	                            IgcCategoryHighlightLayerComponent.htmlTagName,
	                            IgcCategoryHighlightLayerComponent);
	                    }
	            }
	/**
	 * Gets whether the series is an annotation layer displayed only when hovering over the chart.
	*/
	get isAnnotationHoverLayer() : boolean {
		return (this.i.eu as boolean);
	}
	/**
	 * Gets or sets the axis to target this annotation to. If null, this annotation targets all category axes simultaneously.
	*/
	get targetAxis() : IgcCategoryAxisBaseComponent {
	                                        const r = this.i.aas;
	                                        if (r == null) {
	                                            return null;
	                                        }
	                                        
	                                        if (!(r as any).externalObject) {
	                                            let e = IgcCategoryAxisBaseComponent._createFromInternal(r);
	                                            if (e) {
	                                                (e as any)._implementation = r;
	                                            }
	                                            (r as any).externalObject = e;
	                                        }
		return (r as any).externalObject;
	}
	set targetAxis(v: IgcCategoryAxisBaseComponent) {
	                                        if (v != null && this._stylingContainer && (v as any)._styling) (v as any)._styling(this._stylingContainer, this, this);
	
		v == null ? this.i.aas = null : this.i.aas = v.i;
	}
	
	            private _targetAxisName: string = null;
	            /**
	            * Gets or sets the name to use to resolve targetAxis from markup.
	            */
	            public get targetAxisName(): string {
	                return this._targetAxisName;
	            }
	            public set targetAxisName(v: string) {
	                this._targetAxisName = v;                
	            }
	/**
	 * Gets or sets whether to use value interpolation when drawing a line through the best value for the pointer position.
	*/
	get useInterpolation() : boolean {
		return (this.i.aav as boolean);
	}
	set useInterpolation(v: boolean) {
		this.i.aav = ensureBool(v);
	                                        this._a("useInterpolation", this.i.aav);
	}
	/**
	 * Gets or sets the width to use for the highlight region if drawing a band rather than filling a category.
	*/
	get bandHighlightWidth() : number {
		return (this.i.aaw as number);
	}
	set bandHighlightWidth(v: number) {
		this.i.aaw = +v;
	                                        this._a("bandHighlightWidth", this.i.aaw);
	}
	
	             public bindAxes(axes: IgcAxisComponent[]) {
	                super.bindAxes(axes);
	                	
	            for (let i = 0; i < axes.length; i++) {
	                if (this.targetAxisName && this.targetAxisName.length > 0 &&
	                    axes[i].name == this.targetAxisName) {
	                    this.targetAxis = axes[i] as IgcCategoryAxisBaseComponent;
	                }
	            }
	
	}
	
	    public findByName(name: string): any {
	        
	    var baseResult = super.findByName(name);
	    if (baseResult)
	    {
	        return baseResult;
	    }
	
	if (this.targetAxis && (this.targetAxis as any).name && (this.targetAxis as any).name == name) { return this.targetAxis; }
	
	        return null;
	    }
	
	        protected _styling(container: any, component: any, parent?: any) {
	            super._styling(container, component, parent);
	
	            this._inStyling = true;
	            if (this.targetAxis && (this.targetAxis as any)._styling) {
	    (this.targetAxis as any)._styling(container, component, this);
	}
	
	            this._inStyling = false;
	        }
}
