import { UserAnnotationAxisDataContext } from "./UserAnnotationAxisDataContext";
import { UserShapeAnnotation } from "./UserShapeAnnotation";
import { Base, Type, markType } from "igniteui-core/type";

/**
 * @hidden 
 */
export class UserAnnotationShapeDataContext extends UserAnnotationAxisDataContext {
	static $t: Type = markType(UserAnnotationShapeDataContext, 'UserAnnotationShapeDataContext', (<any>UserAnnotationAxisDataContext).$);
	private g: UserShapeAnnotation = null;
	constructor(a: UserShapeAnnotation) {
		super(a);
		this.g = a;
	}
	get overlayText(): string {
		if (this.g != null) {
			return this.g.overlayText;
		}
		return null;
	}
}


