import { IgcIndicatorProxyModule } from './igc-indicator-proxy-module';

import { IgcNegativeVolumeIndexIndicatorComponent } from './igc-negative-volume-index-indicator-component';
import { NegativeVolumeIndexIndicator } from './NegativeVolumeIndexIndicator';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcNegativeVolumeIndexIndicatorModule {
    public static register(): void {
IgcIndicatorProxyModule.register();
        IgcNegativeVolumeIndexIndicatorComponent.register();
        TypeRegistrar.registerCons("IgcNegativeVolumeIndexIndicatorComponent", IgcNegativeVolumeIndexIndicatorComponent);
        TypeRegistrar.register("NegativeVolumeIndexIndicator", (<any>NegativeVolumeIndexIndicator).$type);
    }
}
