import { IgRect } from 'igniteui-core/IgRect'
import { IgSize } from 'igniteui-core/IgSize'
import { IgPoint } from 'igniteui-core/IgPoint'
import { IgDataTemplate } from 'igniteui-core/IgDataTemplate'
import { IgcHTMLElement } from 'igniteui-core/igc-html-element'
import { IgcSeriesComponent } from "./igc-series-component";
import { IgcSeriesViewerComponent } from "./igc-series-viewer-component";
import { ChartMouseEventArgs as ChartMouseEventArgs_internal } from "./ChartMouseEventArgs";
import { fromPoint, toPoint } from "igniteui-core/componentUtil";

/**
 * Provides data for IgxDataChartComponent mouse button related events.
*/
export class IgcChartMouseEventArgs
{
	protected _implementation: any;
	                            /**
	                             * @hidden 
	                             */
	public get i() : ChartMouseEventArgs_internal {
		return this._implementation;
	}
	private onImplementationCreated() {
		
	}
	constructor() {									
	}
	protected _provideImplementation(i: any) {
	    this._implementation = i;
	    (<any>this._implementation).externalObject = this;
	this.onImplementationCreated();
	                                if ((this as any)._initializeAdapters) {
	                                    (this as any)._initializeAdapters();
	                                }
	
	}
	/**
	 * Gets a reference to the object that raised the event.
	*/
	get originalSource() : any {
		return this.i.originalSource as any;
	}
	/**
	 * Gets the ItemsSource item associated with the current event.
	*/
	get item() : any {
		return this.i.item as any;
	}
	set item(v: any) {
	                                        this.i.item = v;
	}
	/**
	 * Gets the series associated with the current event.
	*/
	get series() : IgcSeriesComponent {
	                                        const r = this.i.series;
	                                        if (r == null) {
	                                            return null;
	                                        }
	                                        
	                                        if (!(r as any).externalObject) {
	                                            let e = IgcSeriesComponent._createFromInternal(r);
	                                            if (e) {
	                                                (e as any)._implementation = r;
	                                            }
	                                            (r as any).externalObject = e;
	                                        }
		return (r as any).externalObject;
	}
	set series(v: IgcSeriesComponent) {
		v == null ? this.i.series = null : this.i.series = v.i;
	}
	/**
	 * Gets the mouse position relative to the plot area.
	*/
	get plotAreaPosition() : IgPoint {
		return fromPoint(this.i.plotAreaPosition);
	}
	set plotAreaPosition(v: IgPoint) {
		this.i.plotAreaPosition = toPoint(v);
	}
	/**
	 * Gets the mouse position relative to the chart.
	*/
	get chartPosition() : IgPoint {
		return fromPoint(this.i.chartPosition);
	}
	/**
	
	*/
	get worldPosition() : IgPoint {
		return fromPoint(this.i.worldPosition);
	}
	set worldPosition(v: IgPoint) {
		this.i.worldPosition = toPoint(v);
	}
	/**
	 * Gets the Chart associated with the current event.
	*/
	get chart() : IgcSeriesViewerComponent {
	                                        const r = this.i.chart;
	                                        if (r == null) {
	                                            return null;
	                                        }
	                                        
		return (r as any).externalObject;
	}
	set chart(v: IgcSeriesViewerComponent) {
		v == null ? this.i.chart = null : this.i.chart = v.i;
	}
	/**
	 * Provides a human readable description of the mouse button event.
	
	*/
	public toString() : string {
	                        
		let iv = this.i.toString();
	                        return (iv);
	}
	/**
	 * Returns the x- and y- coordinates of the mouse pointer position, optionally evaluated
	 * against the origin of a supplied UIElement.
	
	* @param relativeTo  * Any UIElement derived object that is contained by the the engine plug-in
	 * and connected to the object tree. To specify the object relative to the overall the engine
	 * coordinate system, use a relativeTo value of null.
	*/
	public getPosition(relativeTo: any) : IgPoint {
	                        
		let iv = this.i.getPosition(relativeTo);
	                        return fromPoint(iv);
	}
}
