import { IgRect } from 'igniteui-core/IgRect'
import { IgSize } from 'igniteui-core/IgSize'
import { IgPoint } from 'igniteui-core/IgPoint'
import { IgDataTemplate } from 'igniteui-core/IgDataTemplate'
import { IgcHTMLElement } from 'igniteui-core/igc-html-element'
import { SeriesMatcher as SeriesMatcher_internal } from "./SeriesMatcher";

export class IgcSeriesMatcher
{

protected createImplementation() : SeriesMatcher_internal
{
	return new SeriesMatcher_internal();
}
	protected _implementation: any;
	                            /**
	                             * @hidden 
	                             */
	public get i() : SeriesMatcher_internal {
		return this._implementation;
	}
	private onImplementationCreated() {
		
	}
	constructor() {
	this._implementation = this.createImplementation();
	(<any>this._implementation).externalObject = this;
	this.onImplementationCreated();
	                                if ((this as any)._initializeAdapters) {
	                                    (this as any)._initializeAdapters();
	                                }
	
	}
	protected _provideImplementation(i: any) {
	    this._implementation = i;
	    (<any>this._implementation).externalObject = this;
	this.onImplementationCreated();
	                                if ((this as any)._initializeAdapters) {
	                                    (this as any)._initializeAdapters();
	                                }
	
	}
	/**
	 * If set, tries to match a series based on its name.
	*/
	get name() : string {
		return (this.i.g as string);
	}
	set name(v: string) {
		this.i.g = v;
	}
	/**
	 * If set, tries to match a series based on its title.
	*/
	get title() : string {
		return (this.i.h as string);
	}
	set title(v: string) {
		this.i.h = v;
	}
	/**
	 * If set, tries to match a series based on index
	*/
	get index() : number {
		return (this.i.d as number);
	}
	set index(v: number) {
		this.i.d = +v;
	}
	/**
	 * Combined with MemberPath allows you to select a series by member path.
	*/
	get memberPathType() : string {
		return (this.i.f as string);
	}
	set memberPathType(v: string) {
		this.i.f = v;
	}
	/**
	 * If set, tries to match a series based on a member path, combined with MemberPathType.
	*/
	get memberPath() : string {
		return (this.i.e as string);
	}
	set memberPath(v: string) {
		this.i.e = v;
	}
	
	    public findByName(name: string): any {
	        
	    if ((this as any).findEphemera) {
	        if (name && name.indexOf("@@e:") == 0) {
	            return (this as any).findEphemera(name);
	        }
	    }
	
	
	        return null;
	    }
}
