import { IgcIndicatorProxyModule } from './igc-indicator-proxy-module';

import { IgcStandardDeviationIndicatorComponent } from './igc-standard-deviation-indicator-component';
import { StandardDeviationIndicator } from './StandardDeviationIndicator';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcStandardDeviationIndicatorModule {
    public static register(): void {
IgcIndicatorProxyModule.register();
        IgcStandardDeviationIndicatorComponent.register();
        TypeRegistrar.registerCons("IgcStandardDeviationIndicatorComponent", IgcStandardDeviationIndicatorComponent);
        TypeRegistrar.register("StandardDeviationIndicator", (<any>StandardDeviationIndicator).$type);
    }
}
