import { IgcIndicatorProxyModule } from './igc-indicator-proxy-module';

import { IgcChaikinOscillatorIndicatorComponent } from './igc-chaikin-oscillator-indicator-component';
import { ChaikinOscillatorIndicator } from './ChaikinOscillatorIndicator';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcChaikinOscillatorIndicatorModule {
    public static register(): void {
IgcIndicatorProxyModule.register();
        IgcChaikinOscillatorIndicatorComponent.register();
        TypeRegistrar.registerCons("IgcChaikinOscillatorIndicatorComponent", IgcChaikinOscillatorIndicatorComponent);
        TypeRegistrar.register("ChaikinOscillatorIndicator", (<any>ChaikinOscillatorIndicator).$type);
    }
}
