import { IgcHorizontalAnchoredCategorySeriesProxyModule } from './igc-horizontal-anchored-category-series-proxy-module';

import { IgcWaterfallSeriesComponent } from './igc-waterfall-series-component';
import { WaterfallSeries } from './WaterfallSeries';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcWaterfallSeriesModule {
    public static register(): void {
IgcHorizontalAnchoredCategorySeriesProxyModule.register();
        IgcWaterfallSeriesComponent.register();
        TypeRegistrar.registerCons("IgcWaterfallSeriesComponent", IgcWaterfallSeriesComponent);
        TypeRegistrar.register("WaterfallSeries", (<any>WaterfallSeries).$type);
    }
}
