import { IgRect } from 'igniteui-core/IgRect'
import { IgSize } from 'igniteui-core/IgSize'
import { IgPoint } from 'igniteui-core/IgPoint'
import { IgDataTemplate } from 'igniteui-core/IgDataTemplate'
import { IgcHTMLElement } from 'igniteui-core/igc-html-element'
import { FunnelSliceEventArgs as FunnelSliceEventArgs_internal } from "./FunnelSliceEventArgs";
import { fromRect, toRect, fromPoint, toPoint } from "igniteui-core/componentUtil";

/**
 * Information about the clicked slice.
*/
export class IgcFunnelSliceEventArgs
{

protected createImplementation() : FunnelSliceEventArgs_internal
{
	return new FunnelSliceEventArgs_internal();
}
	protected _implementation: any;
	                            /**
	                             * @hidden 
	                             */
	public get i() : FunnelSliceEventArgs_internal {
		return this._implementation;
	}
	private onImplementationCreated() {
		
	}
	constructor() {
	this._implementation = this.createImplementation();
	(<any>this._implementation).externalObject = this;
	this.onImplementationCreated();
	                                if ((this as any)._initializeAdapters) {
	                                    (this as any)._initializeAdapters();
	                                }
	
	}
	protected _provideImplementation(i: any) {
	    this._implementation = i;
	    (<any>this._implementation).externalObject = this;
	this.onImplementationCreated();
	                                if ((this as any)._initializeAdapters) {
	                                    (this as any)._initializeAdapters();
	                                }
	
	}
	/**
	 * The index of the slice.
	*/
	get index() : number {
		return (this.i.index as number);
	}
	set index(v: number) {
		this.i.index = +v;
	}
	/**
	 * The bounds of the slice.
	*/
	get bounds() : IgRect {
		return fromRect(this.i.bounds);
	}
	set bounds(v: IgRect) {
		this.i.bounds = toRect(v);
	}
	/**
	 * The data item for the clicked slice.
	*/
	get item() : any {
		return this.i.item as any;
	}
	set item(v: any) {
	                                        this.i.item = v;
	}
	/**
	 * The position of the mouse relative to the funnel chart.
	*/
	get position() : IgPoint {
		return fromPoint(this.i.position);
	}
	set position(v: IgPoint) {
		this.i.position = toPoint(v);
	}
}
