import { IgcDataChartToolbarIconsModule } from './igc-data-chart-toolbar-icons-module';
import { DataChartToolbarFactoryManager } from './DataChartToolbarFactoryManager';
import { CategoryChartToolbarFactoryManager } from './CategoryChartToolbarFactoryManager';
import { TypeRegistrar } from 'igniteui-core/type';


export class IgcCategoryChartToolbarModule {
    public static register() {
                IgcDataChartToolbarIconsModule.register();
        TypeRegistrar.register('DataChartToolbarFactoryManager', (DataChartToolbarFactoryManager as any).$type);
DataChartToolbarFactoryManager.register();
        TypeRegistrar.register('CategoryChartToolbarFactoryManager', (CategoryChartToolbarFactoryManager as any).$type);
CategoryChartToolbarFactoryManager.register();

    }
}