import { IgcIndicatorProxyModule } from './igc-indicator-proxy-module';

import { IgcAverageDirectionalIndexIndicatorComponent } from './igc-average-directional-index-indicator-component';
import { AverageDirectionalIndexIndicator } from './AverageDirectionalIndexIndicator';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcAverageDirectionalIndexIndicatorModule {
    public static register(): void {
IgcIndicatorProxyModule.register();
        IgcAverageDirectionalIndexIndicatorComponent.register();
        TypeRegistrar.registerCons("IgcAverageDirectionalIndexIndicatorComponent", IgcAverageDirectionalIndexIndicatorComponent);
        TypeRegistrar.register("AverageDirectionalIndexIndicator", (<any>AverageDirectionalIndexIndicator).$type);
    }
}
