import { IgRect } from 'igniteui-core/IgRect'
import { IgSize } from 'igniteui-core/IgSize'
import { IgPoint } from 'igniteui-core/IgPoint'
import { IgDataTemplate } from 'igniteui-core/IgDataTemplate'
import { IgcHTMLElement } from 'igniteui-core/igc-html-element'
import { IgcSeriesComponent } from "./igc-series-component";
import { IgcSeriesMatcher } from "./igc-series-matcher";
import { ChartSelection as ChartSelection_internal } from "./ChartSelection";

/**
 * Represents a selected item within the chart. This should be treated as immutable while in the selected items collection. Changes while part of the collection will not be respected.
*/
export class IgcChartSelection
{

protected createImplementation() : ChartSelection_internal
{
	return new ChartSelection_internal();
}
	protected _implementation: any;
	                            /**
	                             * @hidden 
	                             */
	public get i() : ChartSelection_internal {
		return this._implementation;
	}
	private onImplementationCreated() {
		
	}
	constructor() {
	this._implementation = this.createImplementation();
	(<any>this._implementation).externalObject = this;
	this.onImplementationCreated();
	                                if ((this as any)._initializeAdapters) {
	                                    (this as any)._initializeAdapters();
	                                }
	
	}
	protected _provideImplementation(i: any) {
	    this._implementation = i;
	    (<any>this._implementation).externalObject = this;
	this.onImplementationCreated();
	                                if ((this as any)._initializeAdapters) {
	                                    (this as any)._initializeAdapters();
	                                }
	
	}
	get item() : any {
		return this.i.item as any;
	}
	set item(v: any) {
	                                        this.i.item = v;
	}
	get series() : IgcSeriesComponent {
	                                        const r = this.i.series;
	                                        if (r == null) {
	                                            return null;
	                                        }
	                                        
	                                        if (!(r as any).externalObject) {
	                                            let e = IgcSeriesComponent._createFromInternal(r);
	                                            if (e) {
	                                                (e as any)._implementation = r;
	                                            }
	                                            (r as any).externalObject = e;
	                                        }
		return (r as any).externalObject;
	}
	set series(v: IgcSeriesComponent) {
		v == null ? this.i.series = null : this.i.series = v.i;
	}
	/**
	 * If set, allows for selecting a series based on a matcher. This should resolve to a single static series at the time that the chart selection is added to selected items. 
	 * It will not be re-evaluated while the ChartSelection is in the selected items.
	*/
	get matcher() : IgcSeriesMatcher {
	                                        const r = this.i.c;
	                                        if (r == null) {
	                                            return null;
	                                        }
	                                        
	                                        if (!(r as any).externalObject) {
	                                            let e = new IgcSeriesMatcher();
	                                            if ((r as any).$type) {
	                                                (e as any)._implementation = r;
	                                            } else {
	                                                if ((e.i as any).setNativeElement) {
	                                                    (e.i as any).setNativeElement(r);
	                                                }
	                                            }
	                                            (r as any).externalObject = e;
	                                        }
		return (r as any).externalObject;
	}
	set matcher(v: IgcSeriesMatcher) {
		v == null ? this.i.c = null : this.i.c = v.i;
	}
	
	    public findByName(name: string): any {
	        
	    if ((this as any).findEphemera) {
	        if (name && name.indexOf("@@e:") == 0) {
	            return (this as any).findEphemera(name);
	        }
	    }
	
	if (this.series && (this.series as any).name && (this.series as any).name == name) { return this.series; }
	if (this.matcher && (this.matcher as any).name && (this.matcher as any).name == name) { return this.matcher; }
	
	        return null;
	    }
	public equals(other: any) : boolean {
	                        
		let iv = this.i.equals(other);
	                        return (iv);
	}
}
