import { IgcHorizontalAnchoredCategorySeriesProxyModule } from './igc-horizontal-anchored-category-series-proxy-module';

import { IgcSplineSeriesComponent } from './igc-spline-series-component';
import { SplineSeries } from './SplineSeries';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcSplineSeriesModule {
    public static register(): void {
IgcHorizontalAnchoredCategorySeriesProxyModule.register();
        IgcSplineSeriesComponent.register();
        TypeRegistrar.registerCons("IgcSplineSeriesComponent", IgcSplineSeriesComponent);
        TypeRegistrar.register("SplineSeries", (<any>SplineSeries).$type);
    }
}
