import { IgcScatterSeriesComponent } from './igc-scatter-series-component';
import { ScatterSeries } from './ScatterSeries';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcScatterSeriesModule {
    public static register(): void {
        IgcScatterSeriesComponent.register();
        TypeRegistrar.registerCons("IgcScatterSeriesComponent", IgcScatterSeriesComponent);
        TypeRegistrar.register("ScatterSeries", (<any>ScatterSeries).$type);
    }
}
