import { WebComponentRenderer, WebComponentWrapper } from 'igniteui-core/web-component-renderer';
import { TypeRegistrar, IEnumerable } from 'igniteui-core/type';
import { IgcPieChartBaseComponent } from './igc-pie-chart-base-component';
import { DataChartStylingDefaults } from './DataChartStylingDefaults';
import { XamPieChart } from './XamPieChart';
import { IgcDataContext } from 'igniteui-core/igc-data-context';
import { getAllPropertyNames, toSpinal, initializePropertiesFromCss, NamePatcher } from "igniteui-core/componentUtil";
import { RegisterElementHelper } from 'igniteui-core/module-manager';

export class IgcPieChartComponent extends IgcPieChartBaseComponent {
	private container: WebComponentWrapper;

    private _height: string;
    private _width: string;

    set height(value: string) {
        this._height = value;
        this.style.height = value;
        this.notifyContainerResized();
    }
    get height(): string {
        return this._height;
    }

    set width(value: string) {
        this._width = value;
        this.style.width = value;
        this.notifyContainerResized();
    }
    get width(): string {
        return this._width;
    }

    public notifyContainerResized() {
        this._chart.notifyContainerResized();
    }

    private _renderer: WebComponentRenderer;

	constructor() {
        super();

        
        if ((this as any)._styling) {
            NamePatcher.ensureStylablePatched(Object.getPrototypeOf(this));
        }
        this._renderer = new WebComponentRenderer(this,
            document,
            true, DataChartStylingDefaults);

        this._implementation = this.createImplementation();
        this.container = this._renderer.createElement("div");
        this._renderer.updateRoot(this.container);
        //this._renderer.rootWrapper.append(this._container);
        this.container.setStyleProperty("display", "block");
        this.container.setStyleProperty("width", "100%");
        this.container.setStyleProperty("height", "100%");
        var root: any;
        root = this.container;
        if (this.container.getNativeElement() != null) {
            root = this.container.getNativeElement();
        }
		
		this._wrapper = this._renderer;
		var chart = this.i;
		this._chart = <XamPieChart>chart;
        
		chart.provideContainer(this._renderer);
        this.bindData();
        
        chart.notifyContainerResized();
        this._renderer.addSizeWatcher(() => {
            this._chart.notifyContainerResized();
        });
    }

    private _disconnected = false;
    disconnectedCallback() {
        this._disconnected = true;
        if (this.i) {
            this.i.onDetachedFromUI();
        }
    }

    connectedCallback() {
        if (this._disconnected) {
            this._disconnected = false;
            if (this.i) {
                this.i.onAttachedToUI();
            }
            return;
        }

        this.classList.add("ig-pie-chart");
        this.classList.add("igc-pie-chart");

        this.appendChild(this.container.getNativeElement());
        this._attached = true;
        this.style.display = "block";
        this.style.height = this._height;
        this.style.width = this._width;
        this._flushQueuedAttributes();
        // supports themes or custom properties set in CSS 
        this._styling(this, this);
    }

    public destroy() {
        this._chart.destroy();
        this._wrapper.destroy();
    }

	private _wrapper: WebComponentRenderer;

	protected createImplementation() {
		return new XamPieChart();
	}

    public get i(): XamPieChart {
		return this._implementation;
	}

    protected createSeriesComponent(type: string): any {
        if (TypeRegistrar.isRegistered(type)) {
            let s = TypeRegistrar.create(type);
            (<any>s).owner = this;
            (<any>s)._provideRenderer(this._renderer);
            return s;
        } else {
            //we shouldn't get here, hopefully.
            throw Error("series type not loaded: " + type);
        }
    }

    private _chart: XamPieChart;

    private _dataSource: any[]= null;
    set dataSource(value: any[]) {
		this._dataSource = value;
		this.bindData();
	}
	get dataSource(): any[] {
		return this._dataSource;
	}

	bindData() {
        if (this._chart != null && this._chart !== undefined) {
            this._chart.itemsSource = <IEnumerable><any>this._dataSource;
        }
    }

    /**
	 * Gets or sets the legend used for the current chart.
	*/
    get legend(): any {
        if (this.i.legend != null)
            return (<any>this.i.legend).externalObject;
    }
    set legend(v: any) {
        if (v != undefined && v != null)
            this.i.legend = v.i;
    }

    
    

    
    	
	                private static _observedAttributesIgcPieChartComponent: string[] = null;
	                static get observedAttributes() {
	                    if (IgcPieChartComponent._observedAttributesIgcPieChartComponent == null) {
	                        let names = getAllPropertyNames(IgcPieChartComponent);
	    for (let i = 0; i < names.length; i++) {
	                            names[i] = toSpinal(names[i]);
	    }
	    IgcPieChartComponent._observedAttributesIgcPieChartComponent = names;
	                    }
	                    return IgcPieChartComponent._observedAttributesIgcPieChartComponent;               
	                }                 
	            

    	
	                public static htmlTagName: string = "igc-pie-chart";
	                protected static _isElementRegistered = false;
	
	                public static register() {
	                    if (!IgcPieChartComponent._isElementRegistered) {
	                        IgcPieChartComponent._isElementRegistered = true;
	                        RegisterElementHelper.registerElement(
	                            IgcPieChartComponent.htmlTagName,
	                            IgcPieChartComponent);
	                    }
	            }

	

    

    

	

    

    //@@ZoneRunner
}
