import { Base, Type, markType, getInstanceType } from "igniteui-core/type";
import { IOverlayProxy, IOverlayProxy_$type } from "./IOverlayProxy";
import { Series } from "./Series";
import { FinancialOverlay } from "./FinancialOverlay";
import { FinancialSeries } from "./FinancialSeries";
import { CategoryAxisBase } from "./CategoryAxisBase";
import { NumericYAxis } from "./NumericYAxis";

/**
 * @hidden 
 */
export class OverlayProxy extends Base implements IOverlayProxy {
	static $t: Type = markType(OverlayProxy, 'OverlayProxy', (<any>Base).$, [IOverlayProxy_$type]);
	matchesType(a: Series): boolean {
		if (a.fc) {
			return true;
		}
		return false;
	}
	setCloseMemberPath(a: Series, b: string): void {
		(<FinancialOverlay>a).zv = b;
	}
	setHighMemberPath(a: Series, b: string): void {
		(<FinancialOverlay>a).z8 = b;
	}
	setLowMemberPath(a: Series, b: string): void {
		(<FinancialOverlay>a).aad = b;
	}
	setMultiplier(a: Series, b: number): void {
		if (getInstanceType(a).typeName == "BollingerBandsOverlay") {
			let s_ = a;
			let p_ = b;
			s_['multiplier'] = p_;
		}
	}
	setOpenMemberPath(a: Series, b: string): void {
		(<FinancialOverlay>a).aah = b;
	}
	setVolumeMemberPath(a: Series, b: string): void {
		(<FinancialOverlay>a).aal = b;
	}
	setXAxis(a: Series, b: CategoryAxisBase): void {
		(<FinancialOverlay>a).xr = b;
	}
	setYAxis(a: Series, b: NumericYAxis): void {
		(<FinancialOverlay>a).ya = b;
	}
}


