import { IgRect } from 'igniteui-core/IgRect'
import { IgSize } from 'igniteui-core/IgSize'
import { IgPoint } from 'igniteui-core/IgPoint'
import { IgDataTemplate } from 'igniteui-core/IgDataTemplate'
import { IgcHTMLElement } from 'igniteui-core/igc-html-element'
import { IgcFinancialIndicatorComponent } from "./igc-financial-indicator-component";
import { IgcFinancialSeriesComponent } from "./igc-financial-series-component";
import { IgcSeriesComponent } from "./igc-series-component";
import { StrategyBasedIndicator } from "./StrategyBasedIndicator";
import { getAllPropertyNames, fromSpinal, toSpinal } from "igniteui-core/componentUtil";

/**
 * A base class for indicator series with simple calculations that separates the calculation
 * responsibility from the other responsibilities of the financial series, this enables
 * easier unit testing and decoupling of individual calculation strategies.
 * A contract is defined between the financial series and these simple indicator calculations 
 * detailing the data which the series agrees to provide the simple indicator calculations, 
 * this contract is defined by 
 * FinancialCalculationDataSource. If more 
 * complex interactions are needed between the indicator calculation and the series, the 
 * indicators should instead derive from 
 * FinancialIndicator directly, or some 
 * derivative other than 
 * StrategyBasedIndicator
*/
export abstract class IgcStrategyBasedIndicatorComponent extends IgcFinancialIndicatorComponent
{


	/**
	                             * @hidden 
	                             */
	                            public get i() : StrategyBasedIndicator {
		return this._implementation;
	}
	constructor() {
		super()
	                                     
	}
	
	    connectedCallback() {
	        if (super["connectedCallback"]) {
	            super["connectedCallback"]();
	        }
	        if ((<any>this.i).connectedCallback) {
	            (<any>this.i).connectedCallback();
	        }
	        
	        if (!this._attached) {
	            this._attached = true;
	            this._flushQueuedAttributes();
	        }
	    }
	    disconnectedCallback() {
	        if (super["disconnectedCallback"]) {
	            super["disconnectedCallback"]();
	        }
	        if ((<any>this.i).disconnectedCallback) {
	            (<any>this.i).disconnectedCallback();
	        }
	        if (this._attached) {
	            this._attached = false;
	        }
	    }
	
	                private static _observedAttributesIgcStrategyBasedIndicatorComponent: string[] = null;
	                static get observedAttributes() {
	                    if (IgcStrategyBasedIndicatorComponent._observedAttributesIgcStrategyBasedIndicatorComponent == null) {
	                        let names = getAllPropertyNames(IgcStrategyBasedIndicatorComponent);
	    for (let i = 0; i < names.length; i++) {
	                            names[i] = toSpinal(names[i]);
	    }
	    IgcStrategyBasedIndicatorComponent._observedAttributesIgcStrategyBasedIndicatorComponent = names;
	                    }
	                    return IgcStrategyBasedIndicatorComponent._observedAttributesIgcStrategyBasedIndicatorComponent;               
	                }                 
	            
}
