import { IgcIndicatorProxyModule } from './igc-indicator-proxy-module';

import { IgcDetrendedPriceOscillatorIndicatorComponent } from './igc-detrended-price-oscillator-indicator-component';
import { DetrendedPriceOscillatorIndicator } from './DetrendedPriceOscillatorIndicator';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcDetrendedPriceOscillatorIndicatorModule {
    public static register(): void {
IgcIndicatorProxyModule.register();
        IgcDetrendedPriceOscillatorIndicatorComponent.register();
        TypeRegistrar.registerCons("IgcDetrendedPriceOscillatorIndicatorComponent", IgcDetrendedPriceOscillatorIndicatorComponent);
        TypeRegistrar.register("DetrendedPriceOscillatorIndicator", (<any>DetrendedPriceOscillatorIndicator).$type);
    }
}
