import { IgcIndicatorProxyModule } from './igc-indicator-proxy-module';

import { IgcStochRSIIndicatorComponent } from './igc-stoch-rsi-indicator-component';
import { StochRSIIndicator } from './StochRSIIndicator';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcStochRSIIndicatorModule {
    public static register(): void {
IgcIndicatorProxyModule.register();
        IgcStochRSIIndicatorComponent.register();
        TypeRegistrar.registerCons("IgcStochRSIIndicatorComponent", IgcStochRSIIndicatorComponent);
        TypeRegistrar.register("StochRSIIndicator", (<any>StochRSIIndicator).$type);
    }
}
