import { IgcTimeAxisIntervalComponent } from './igc-time-axis-interval-component';
import { TimeAxisInterval } from './TimeAxisInterval';
import { TypeRegistrar } from 'igniteui-core/type';
import { IgcTimeAxisIntervalCollection } from './igc-time-axis-interval-collection';
import { TimeAxisIntervalCollection } from './TimeAxisIntervalCollection';


export class IgcTimeAxisIntervalModule {
    public static register(): void {
        IgcTimeAxisIntervalComponent.register();
        TypeRegistrar.registerCons("IgcTimeAxisIntervalComponent", IgcTimeAxisIntervalComponent);
        TypeRegistrar.register("TimeAxisInterval", (<any>TimeAxisInterval).$type);
        TypeRegistrar.registerCons("IgcTimeAxisIntervalCollection", IgcTimeAxisIntervalCollection);
        TypeRegistrar.register("TimeAxisIntervalCollection", (<any>TimeAxisIntervalCollection).$type);     

    }
}
