import { IgRect } from 'igniteui-core/IgRect'
import { IgSize } from 'igniteui-core/IgSize'
import { IgPoint } from 'igniteui-core/IgPoint'
import { IgDataTemplate } from 'igniteui-core/IgDataTemplate'
import { IgcHTMLElement } from 'igniteui-core/igc-html-element'
import { CalloutContentUpdatingEventArgs as CalloutContentUpdatingEventArgs_internal } from "./CalloutContentUpdatingEventArgs";

/**
 * Represents event arguments for updating content of callout layer
*/
export class IgcCalloutContentUpdatingEventArgs
{

protected createImplementation() : CalloutContentUpdatingEventArgs_internal
{
	return new CalloutContentUpdatingEventArgs_internal();
}
	protected _implementation: any;
	                            /**
	                             * @hidden 
	                             */
	public get i() : CalloutContentUpdatingEventArgs_internal {
		return this._implementation;
	}
	private onImplementationCreated() {
		
	}
	constructor() {
	this._implementation = this.createImplementation();
	(<any>this._implementation).externalObject = this;
	this.onImplementationCreated();
	                                if ((this as any)._initializeAdapters) {
	                                    (this as any)._initializeAdapters();
	                                }
	
	}
	protected _provideImplementation(i: any) {
	    this._implementation = i;
	    (<any>this._implementation).externalObject = this;
	this.onImplementationCreated();
	                                if ((this as any)._initializeAdapters) {
	                                    (this as any)._initializeAdapters();
	                                }
	
	}
	/**
	 * Gets data X-value associated with callout layer
	*/
	get xValue() : any {
		return this.i.c as any;
	}
	set xValue(v: any) {
	                                        this.i.c = v;
	}
	/**
	 * Gets data Y-value associated with callout layer
	*/
	get yValue() : any {
		return this.i.d as any;
	}
	set yValue(v: any) {
	                                        this.i.d = v;
	}
	/**
	 * Gets data item associated with callout layer
	*/
	get item() : any {
		return this.i.item as any;
	}
	set item(v: any) {
	                                        this.i.item = v;
	}
	/**
	 * Gets or sets content displayed by callout layer
	*/
	get content() : any {
		return this.i.a as any;
	}
	set content(v: any) {
	                                        this.i.a = v;
	}
}
