import { InteractionMessage } from "./InteractionMessage";
import { Point, Base, Type, markType } from "igniteui-core/type";

/**
 * @hidden 
 */
export class MouseLeaveMessage extends InteractionMessage {
	static $t: Type = markType(MouseLeaveMessage, 'MouseLeaveMessage', (<any>InteractionMessage).$);
	private b: Point = null;
	get c(): Point {
		return this.b;
	}
	set c(a: Point) {
		this.b = a;
	}
	toString(): string {
		return "MouseLeaveMessage[" + this.c.toString() + "]";
	}
}


