/**
 * Represents a legend that displays information about each series, most often used in financial charting.
*/
export class IgcFinancialLegendComponent extends IgcLegendBaseComponent {

    private container: WebComponentWrapper;

    private initializeContent() {

    }

    constructor() {
        super();

        let container: HTMLElement;
        if (document) {
            container = document.createElement("div");
            container.style.display = "block";
            container.style.width = "100%";
            container.style.height = "100%";
        }


        var root: any;
        root = container;
        var ren: WebComponentRenderer = new WebComponentRenderer(
            root, document,
            true,
            DataChartStylingDefaults);
        this.container = ren.getWrapper(container) as WebComponentWrapper;
        this._wrapper = ren;

        this.i.provideContainer(ren);        
    }

    private _wrapper: WebComponentRenderer;

    public destroy() {
        this._wrapper.destroy();
        this.i.provideContainer(null);
    }

    protected createImplementation() {
        return new Legend();
    }

    public get i(): FinancialLegend {
        return this._implementation;
    }

    
    private _disconnected = false;
    disconnectedCallback() {
        this._disconnected = true;
        if (this.i) {
            this.i.onDetachedFromUI();
        }
    }

    connectedCallback() {
        if (this._disconnected) {
            this._disconnected = false;
            if (this.i) {
                this.i.onAttachedToUI();
            }
            return;
        }

        this.classList.add("ig-item-legend");
        this.classList.add("igc-item-legend");

        this.appendChild(this._wrapper.rootWrapper.getNativeElement());
        this._attached = true;
        this.style.display = "block";
        //this.style.height = this._height;
        //this.style.width = this._width;
        this._flushQueuedAttributes();
        // supports themes or custom properties set in CSS 
        //this._styling(this, this);

        this.initializeContent();
    }
	

    	
	                private static _observedAttributesIgcFinancialLegendComponent: string[] = null;
	                static get observedAttributes() {
	                    if (IgcFinancialLegendComponent._observedAttributesIgcFinancialLegendComponent == null) {
	                        let names = getAllPropertyNames(IgcFinancialLegendComponent);
	    for (let i = 0; i < names.length; i++) {
	                            names[i] = toSpinal(names[i]);
	    }
	    IgcFinancialLegendComponent._observedAttributesIgcFinancialLegendComponent = names;
	                    }
	                    return IgcFinancialLegendComponent._observedAttributesIgcFinancialLegendComponent;               
	                }                 
	            

    	
	                public static htmlTagName: string = "igc-financial-legend";
	                protected static _isElementRegistered = false;
	
	                public static register() {
	                    if (!IgcFinancialLegendComponent._isElementRegistered) {
	                        IgcFinancialLegendComponent._isElementRegistered = true;
	                        RegisterElementHelper.registerElement(
	                            IgcFinancialLegendComponent.htmlTagName,
	                            IgcFinancialLegendComponent);
	                    }
	            }

    	/**
	 * Gets if the legend is a financial legend.
	*/
	get isFinancial() : boolean {
		return (this.i.isFinancial as boolean);
	}

    

    

    

    
}
