import { Base, Type, markType } from "igniteui-core/type";
import { StackedSeriesBase } from "./StackedSeriesBase";
import { Series } from "./Series";
import { IFastItemsSource } from "igniteui-core/IFastItemsSource";

/**
 * @hidden 
 */
export class Stacked100DataPreparer extends Base {
	static $t: Type = markType(Stacked100DataPreparer, 'Stacked100DataPreparer');
	static a(a: StackedSeriesBase): void {
		if (a.dp == null) {
			return;
		}
		let b: number = Number.POSITIVE_INFINITY;
		let c: number = Number.NEGATIVE_INFINITY;
		for (let d: number = 0; d < a.dp.count; d++) {
			let e: number = Math.abs(a.abg[d]) + a.abf[d];
			if (e == 0) {
				b = Math.min(b, 0);
				c = Math.max(c, 0);
				continue;
			}
			b = Math.min(b, a.abg[d] / e * 100);
			c = Math.max(c, a.abf[d] / e * 100);
		}
		a.abz = b;
		a.aby = c;
	}
}


