import { IgRect } from 'igniteui-core/IgRect'
import { IgSize } from 'igniteui-core/IgSize'
import { IgPoint } from 'igniteui-core/IgPoint'
import { IgDataTemplate } from 'igniteui-core/IgDataTemplate'
import { IgcHTMLElement } from 'igniteui-core/igc-html-element'
import { IgcAxisComponent } from "./igc-axis-component";
import { IgcAxisMatcher } from "./igc-axis-matcher";
import { IgcUserBaseAnnotation } from "./igc-user-base-annotation";
import { UserAxisAnnotation as UserAxisAnnotation_internal } from "./UserAxisAnnotation";

/**
 * Represents an user annotation for rendering annotation of axis label
*/
export class IgcUserAxisAnnotation extends IgcUserBaseAnnotation
{

protected createImplementation() : UserAxisAnnotation_internal
{
	return new UserAxisAnnotation_internal();
}
	/**
	                             * @hidden 
	                             */
	                            public get i() : UserAxisAnnotation_internal {
		return this._implementation;
	}
	constructor() {
		super();
	}
	/**
	 * Gets or sets the target axis that will display the annotation.
	*/
	get targetAxis() : IgcAxisComponent {
	                                        const r = this.i.targetAxis;
	                                        if (r == null) {
	                                            return null;
	                                        }
	                                        
	                                        if (!(r as any).externalObject) {
	                                            let e = IgcAxisComponent._createFromInternal(r);
	                                            if (e) {
	                                                (e as any)._implementation = r;
	                                            }
	                                            (r as any).externalObject = e;
	                                        }
		return (r as any).externalObject;
	}
	set targetAxis(v: IgcAxisComponent) {
		v == null ? this.i.targetAxis = null : this.i.targetAxis = v.i;
	}
	
	            private _targetAxisName: string = null;
	            /**
	            * Gets or sets the name to use to resolve targetAxis from markup.
	            */
	            public get targetAxisName(): string {
	                return this._targetAxisName;
	            }
	            public set targetAxisName(v: string) {
	                this._targetAxisName = v;                
	            }
	/**
	 * Gets or sets a matcher for matching an axis that will display the annotation.
	*/
	get targetAxisMatcher() : IgcAxisMatcher {
	                                        const r = this.i.targetAxisMatcher;
	                                        if (r == null) {
	                                            return null;
	                                        }
	                                        
	                                        if (!(r as any).externalObject) {
	                                            let e = new IgcAxisMatcher();
	                                            if ((r as any).$type) {
	                                                (e as any)._implementation = r;
	                                            } else {
	                                                if ((e.i as any).setNativeElement) {
	                                                    (e.i as any).setNativeElement(r);
	                                                }
	                                            }
	                                            (r as any).externalObject = e;
	                                        }
		return (r as any).externalObject;
	}
	set targetAxisMatcher(v: IgcAxisMatcher) {
		v == null ? this.i.targetAxisMatcher = null : this.i.targetAxisMatcher = v.i;
	}
	/**
	 * Gets or sets the value that determines location of annotation on axis.
	*/
	get value() : number {
		return (this.i.value as number);
	}
	set value(v: number) {
		this.i.value = +v;
	}
	
	             public bindAxes(axes: IgcAxisComponent[]) {
	                super.bindAxes(axes);
	                	
	            for (let i = 0; i < axes.length; i++) {
	                if (this.targetAxisName && this.targetAxisName.length > 0 &&
	                    axes[i].name == this.targetAxisName) {
	                    this.targetAxis = axes[i] as IgcAxisComponent;
	                }
	            }
	
	}
	
	    public findByName(name: string): any {
	        
	    var baseResult = super.findByName(name);
	    if (baseResult)
	    {
	        return baseResult;
	    }
	
	if (this.targetAxis && (this.targetAxis as any).name && (this.targetAxis as any).name == name) { return this.targetAxis; }
	if (this.targetAxisMatcher && (this.targetAxisMatcher as any).name && (this.targetAxisMatcher as any).name == name) { return this.targetAxisMatcher; }
	
	        return null;
	    }
}
