import { IgcIndicatorProxyModule } from './igc-indicator-proxy-module';

import { IgcMoneyFlowIndexIndicatorComponent } from './igc-money-flow-index-indicator-component';
import { MoneyFlowIndexIndicator } from './MoneyFlowIndexIndicator';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcMoneyFlowIndexIndicatorModule {
    public static register(): void {
IgcIndicatorProxyModule.register();
        IgcMoneyFlowIndexIndicatorComponent.register();
        TypeRegistrar.registerCons("IgcMoneyFlowIndexIndicatorComponent", IgcMoneyFlowIndexIndicatorComponent);
        TypeRegistrar.register("MoneyFlowIndexIndicator", (<any>MoneyFlowIndexIndicator).$type);
    }
}
