import { IgcIndicatorProxyModule } from './igc-indicator-proxy-module';

import { IgcEaseOfMovementIndicatorComponent } from './igc-ease-of-movement-indicator-component';
import { EaseOfMovementIndicator } from './EaseOfMovementIndicator';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcEaseOfMovementIndicatorModule {
    public static register(): void {
IgcIndicatorProxyModule.register();
        IgcEaseOfMovementIndicatorComponent.register();
        TypeRegistrar.registerCons("IgcEaseOfMovementIndicatorComponent", IgcEaseOfMovementIndicatorComponent);
        TypeRegistrar.register("EaseOfMovementIndicator", (<any>EaseOfMovementIndicator).$type);
    }
}
