import { IgcAnnotationLayerProxyModule } from './igc-annotation-layer-proxy-module';

import { IgcCategoryHighlightLayerComponent } from './igc-category-highlight-layer-component';
import { CategoryHighlightLayer } from './CategoryHighlightLayer';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcCategoryHighlightLayerModule {
    public static register(): void {
IgcAnnotationLayerProxyModule.register();
        IgcCategoryHighlightLayerComponent.register();
        TypeRegistrar.registerCons("IgcCategoryHighlightLayerComponent", IgcCategoryHighlightLayerComponent);
        TypeRegistrar.register("CategoryHighlightLayer", (<any>CategoryHighlightLayer).$type);
    }
}
