import { IgcHorizontalAnchoredCategorySeriesComponent } from "./igc-horizontal-anchored-category-series-component";
import { IgcAnchoredCategorySeriesComponent } from "./igc-anchored-category-series-component";
import { IgcCategorySeriesComponent } from "./igc-category-series-component";
import { IgcMarkerSeriesComponent } from "./igc-marker-series-component";
