import { getAllPropertyNames, fromSpinal, toSpinal, ensureBool, toPoint, fromPoint } from "igniteui-core/componentUtil";

/**
 * Represents one part of a stacked series.
*/
export abstract class IgcFragmentBaseComponent extends IgcHorizontalAnchoredCategorySeriesComponent
{


	/**
	                             * @hidden 
	                             */
	                            public get i() : FragmentBase {
		return this._implementation;
	}
	constructor() {
		super()
	                                     
	}
	
	    connectedCallback() {
	        if (super["connectedCallback"]) {
	            super["connectedCallback"]();
	        }
	        if ((<any>this.i).connectedCallback) {
	            (<any>this.i).connectedCallback();
	        }
	        
	        if (!this._attached) {
	            this._attached = true;
	            this._flushQueuedAttributes();
	        }
	    }
	    disconnectedCallback() {
	        if (super["disconnectedCallback"]) {
	            super["disconnectedCallback"]();
	        }
	        if ((<any>this.i).disconnectedCallback) {
	            (<any>this.i).disconnectedCallback();
	        }
	        if (this._attached) {
	            this._attached = false;
	        }
	    }
	
	                private static _observedAttributesIgcFragmentBaseComponent: string[] = null;
	                static get observedAttributes() {
	                    if (IgcFragmentBaseComponent._observedAttributesIgcFragmentBaseComponent == null) {
	                        let names = getAllPropertyNames(IgcFragmentBaseComponent);
	    for (let i = 0; i < names.length; i++) {
	                            names[i] = toSpinal(names[i]);
	    }
	    IgcFragmentBaseComponent._observedAttributesIgcFragmentBaseComponent = names;
	                    }
	                    return IgcFragmentBaseComponent._observedAttributesIgcFragmentBaseComponent;               
	                }                 
	            
	/**
	 * Gets whether the current series is a stack fragment.
	*/
	get isFragment() : boolean {
		return (this.i.isFragment as boolean);
	}
	public getSeriesValuePosition(world: IgPoint, useInterpolation: boolean, skipUnknowns: boolean) : IgPoint {
	                        
		let iv = this.i.ww(toPoint(world), useInterpolation, skipUnknowns);
	                        return fromPoint(iv);
	}
}
