    private createTooltip(): Element {
        if (!TypeRegistrar.isRegistered("IgcTooltipContainerComponent")) {
            return null;
        }
        let cr = TypeRegistrar.create("IgcTooltipContainerComponent");
        let ele: Element = cr;
        let self = this;

        (<any>ele).updateToolTip = function (c, isSubContent?: boolean) {
            if (c.externalObject) {
                c = c.externalObject;
            } else {
                let ext = new IgcDataContext();
                (<any>ext)._implementation = c;
                c = ext;
            }

            if (!isSubContent) {
                if (ele.parentElement != self._container.getNativeElement()) {
                    if (ele.parentElement != null) {
                        ele.parentElement.removeChild(ele);
                    }

                    self._container.getNativeElement().appendChild(ele);
                }
            } else {
                c.isSubContent = true;
            }
            (<any>cr).context = c;
            (<any>ele).style.display = "block";

            return true;
        };
        (<any>ele).hideToolTip = function () {
            (<any>ele).style.display = "none"
        };
        (<any>ele).style.display = "none"

        return cr;
    }

    private _ensureTooltipCreated(series: any) {
        (<any>series)._ensureTooltipCreated(
            () => this.createTooltip(),
            (ele) => {
                let wrapper = new WebComponentWrapper(
                    ele,
                    this._renderer
                );
                (<any>wrapper).updateToolTip = (<any>ele).updateToolTip;
                (<any>wrapper).hideToolTip = (<any>ele).hideToolTip;
                return wrapper;
            });
    }

    private _createXAxis(): any {
        let x = new IgcCategoryXAxisComponent();
        (<any>x)._provideRenderer(this._wrapper);
        return x.i;
    }

    private _createYAxis(): any {
        let y = new IgcNumericYAxisComponent();
        (<any>y).provideRenderer(this._wrapper);
        return y.i;
    }

    private _ensureDefaultTooltip(series: any) {
        if (this._defaultTooltips == null) {
            return;
        }
        this._defaultTooltips["ensureDefaultTooltip"](series);
    }

    private _onDefaultTooltipsReady(cr: any) {
        if (this.i.dataChart) {
            var currSeries = this.i.dataChart.series;
            for (var i = 0; i < currSeries.count; i++) {
                if ((<any>currSeries.item(i)).externalObject.showDefaultTooltip) {
                    this._ensureDefaultTooltip((<any>currSeries.item(i)).externalObject);
                }
            }
        }
    }

    

    	
