import { IgcHorizontalAnchoredCategorySeriesProxyModule } from './igc-horizontal-anchored-category-series-proxy-module';

import { IgcColumnSeriesComponent } from './igc-column-series-component';
import { ColumnSeries } from './ColumnSeries';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcColumnSeriesModule {
    public static register(): void {
IgcHorizontalAnchoredCategorySeriesProxyModule.register();
        IgcColumnSeriesComponent.register();
        TypeRegistrar.registerCons("IgcColumnSeriesComponent", IgcColumnSeriesComponent);
        TypeRegistrar.register("ColumnSeries", (<any>ColumnSeries).$type);
    }
}
