import { IgcFinancialPriceSeriesProxyModule } from './igc-financial-price-series-proxy-module';

import { IgcFinancialPriceSeriesComponent } from './igc-financial-price-series-component';
import { FinancialPriceSeries } from './FinancialPriceSeries';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcFinancialPriceSeriesModule {
    public static register(): void {
IgcFinancialPriceSeriesProxyModule.register();
        IgcFinancialPriceSeriesComponent.register();
        TypeRegistrar.registerCons("IgcFinancialPriceSeriesComponent", IgcFinancialPriceSeriesComponent);
        TypeRegistrar.register("FinancialPriceSeries", (<any>FinancialPriceSeries).$type);
    }
}
