import { UserAnnotationDataContext } from "./UserAnnotationDataContext";
import { UserPointAnnotation } from "./UserPointAnnotation";
import { Base, Type, markType } from "igniteui-core/type";

/**
 * @hidden 
 */
export class UserAnnotationPointDataContext extends UserAnnotationDataContext {
	static $t: Type = markType(UserAnnotationPointDataContext, 'UserAnnotationPointDataContext', (<any>UserAnnotationDataContext).$);
	private e: UserPointAnnotation = null;
	constructor(a: UserPointAnnotation) {
		super(a);
		this.e = a;
	}
	get xValue(): number {
		return this.e.xValue;
	}
	get yValue(): number {
		return this.e.yValue;
	}
}


