import { IgcAnnotationLayerProxyModule } from './igc-annotation-layer-proxy-module';

import { IgcValueLayerComponent } from './igc-value-layer-component';
import { ValueLayer } from './ValueLayer';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcValueLayerModule {
    public static register(): void {
IgcAnnotationLayerProxyModule.register();
        IgcValueLayerComponent.register();
        TypeRegistrar.registerCons("IgcValueLayerComponent", IgcValueLayerComponent);
        TypeRegistrar.register("ValueLayer", (<any>ValueLayer).$type);
    }
}
