import { IgcIndicatorProxyModule } from './igc-indicator-proxy-module';

import { IgcWeightedCloseIndicatorComponent } from './igc-weighted-close-indicator-component';
import { WeightedCloseIndicator } from './WeightedCloseIndicator';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcWeightedCloseIndicatorModule {
    public static register(): void {
IgcIndicatorProxyModule.register();
        IgcWeightedCloseIndicatorComponent.register();
        TypeRegistrar.registerCons("IgcWeightedCloseIndicatorComponent", IgcWeightedCloseIndicatorComponent);
        TypeRegistrar.register("WeightedCloseIndicator", (<any>WeightedCloseIndicator).$type);
    }
}
