import { IgcAnnotationLayerProxyModule } from './igc-annotation-layer-proxy-module';

import { IgcItemToolTipLayerComponent } from './igc-item-tool-tip-layer-component';
import { ItemToolTipLayer } from './ItemToolTipLayer';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcItemToolTipLayerModule {
    public static register(): void {
IgcAnnotationLayerProxyModule.register();
        IgcItemToolTipLayerComponent.register();
        TypeRegistrar.registerCons("IgcItemToolTipLayerComponent", IgcItemToolTipLayerComponent);
        TypeRegistrar.register("ItemToolTipLayer", (<any>ItemToolTipLayer).$type);
    }
}
