	    public findByName(name: string): any {
	        
	    if ((this as any).findEphemera) {
	        if (name && name.indexOf("@@e:") == 0) {
	            return (this as any).findEphemera(name);
	        }
	    }
	
	if (this.labelFormatSpecifiers != null && arrayFindByName(this.labelFormatSpecifiers, name)) { return arrayFindByName(this.labelFormatSpecifiers, name); }
	
	        return null;
	    }
	public resetCachedExtent() {
		this.i.resetCachedExtent();
	}
	public resolveLabelValue() : string {
	                        
		let iv = this.i.resolveLabelValue();
	                        return (iv);
	}
