import { IgcHorizontalAnchoredCategorySeriesProxyModule } from './igc-horizontal-anchored-category-series-proxy-module';

import { IgcAreaSeriesComponent } from './igc-area-series-component';
import { AreaSeries } from './AreaSeries';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcAreaSeriesModule {
    public static register(): void {
IgcHorizontalAnchoredCategorySeriesProxyModule.register();
        IgcAreaSeriesComponent.register();
        TypeRegistrar.registerCons("IgcAreaSeriesComponent", IgcAreaSeriesComponent);
        TypeRegistrar.register("AreaSeries", (<any>AreaSeries).$type);
    }
}
