import { IgcIndicatorProxyModule } from './igc-indicator-proxy-module';

import { IgcForceIndexIndicatorComponent } from './igc-force-index-indicator-component';
import { ForceIndexIndicator } from './ForceIndexIndicator';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcForceIndexIndicatorModule {
    public static register(): void {
IgcIndicatorProxyModule.register();
        IgcForceIndexIndicatorComponent.register();
        TypeRegistrar.registerCons("IgcForceIndexIndicatorComponent", IgcForceIndexIndicatorComponent);
        TypeRegistrar.register("ForceIndexIndicator", (<any>ForceIndexIndicator).$type);
    }
}
