import { IgcTimeAxisLabelFormatComponent } from './igc-time-axis-label-format-component';
import { TimeAxisLabelFormat } from './TimeAxisLabelFormat';
import { TypeRegistrar } from 'igniteui-core/type';
import { IgcTimeAxisLabelFormatCollection } from './igc-time-axis-label-format-collection';
import { TimeAxisLabelFormatCollection } from './TimeAxisLabelFormatCollection';


export class IgcTimeAxisLabelFormatModule {
    public static register(): void {
        IgcTimeAxisLabelFormatComponent.register();
        TypeRegistrar.registerCons("IgcTimeAxisLabelFormatComponent", IgcTimeAxisLabelFormatComponent);
        TypeRegistrar.register("TimeAxisLabelFormat", (<any>TimeAxisLabelFormat).$type);
        TypeRegistrar.registerCons("IgcTimeAxisLabelFormatCollection", IgcTimeAxisLabelFormatCollection);
        TypeRegistrar.register("TimeAxisLabelFormatCollection", (<any>TimeAxisLabelFormatCollection).$type);     

    }
}
