import { IgcIndicatorProxyModule } from './igc-indicator-proxy-module';

import { IgcOnBalanceVolumeIndicatorComponent } from './igc-on-balance-volume-indicator-component';
import { OnBalanceVolumeIndicator } from './OnBalanceVolumeIndicator';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcOnBalanceVolumeIndicatorModule {
    public static register(): void {
IgcIndicatorProxyModule.register();
        IgcOnBalanceVolumeIndicatorComponent.register();
        TypeRegistrar.registerCons("IgcOnBalanceVolumeIndicatorComponent", IgcOnBalanceVolumeIndicatorComponent);
        TypeRegistrar.register("OnBalanceVolumeIndicator", (<any>OnBalanceVolumeIndicator).$type);
    }
}
