import { IgRect } from 'igniteui-core/IgRect'
import { IgSize } from 'igniteui-core/IgSize'
import { IgPoint } from 'igniteui-core/IgPoint'
import { IgDataTemplate } from 'igniteui-core/IgDataTemplate'
import { IgcHTMLElement } from 'igniteui-core/igc-html-element'
import { SliceClickEventArgs as SliceClickEventArgs_internal } from "./SliceClickEventArgs";
import { ensureBool, fromPoint, toPoint, fromRect, toRect, brushToString, stringToBrush } from "igniteui-core/componentUtil";

/**
 * Contains PieChart click event data.
*/
export class IgcSliceClickEventArgs
{
	protected _implementation: any;
	                            /**
	                             * @hidden 
	                             */
	public get i() : SliceClickEventArgs_internal {
		return this._implementation;
	}
	private onImplementationCreated() {
		
	}
	constructor() {									
	}
	protected _provideImplementation(i: any) {
	    this._implementation = i;
	    (<any>this._implementation).externalObject = this;
	this.onImplementationCreated();
	                                if ((this as any)._initializeAdapters) {
	                                    (this as any)._initializeAdapters();
	                                }
	
	}
	/**
	 * Gets or sets whether the slice is selected.
	*/
	get isSelected() : boolean {
		return (this.i.isSelected as boolean);
	}
	set isSelected(v: boolean) {
		this.i.isSelected = ensureBool(v);
	}
	/**
	 * Gets or sets whether the slice is exploded.
	*/
	get isExploded() : boolean {
		return (this.i.isExploded as boolean);
	}
	set isExploded(v: boolean) {
		this.i.isExploded = ensureBool(v);
	}
	/**
	 * Gets whether the current slice is part of the others slice.
	*/
	get isOthersSlice() : boolean {
		return (this.i.isOthersSlice as boolean);
	}
	/**
	 * Gets the index of the slice that was clicked.
	*/
	get index() : number {
		return (this.i.index as number);
	}
	/**
	 * Gets the slice data context.
	*/
	get dataContext() : any {
		return this.i.dataContext as any;
	}
	/**
	 * Holds a reference to the original event that triggered slice click.
	*/
	get originalEvent() : any {
		return this.i.originalEvent as any;
	}
	set originalEvent(v: any) {
	                                        this.i.originalEvent = v;
	}
	/**
	 * Gets the origin location of the slice.
	*/
	get origin() : IgPoint {
		return fromPoint(this.i.origin);
	}
	/**
	 * Gets the radius of the slice.
	*/
	get radius() : number {
		return (this.i.radius as number);
	}
	/**
	 * Gets the bounds of the slice.
	*/
	get bounds() : IgRect {
		return fromRect(this.i.bounds);
	}
	/**
	 * Gets the start angle of the slice.
	*/
	get startAngle() : number {
		return (this.i.startAngle as number);
	}
	/**
	 * Gets the end angle of the slice.
	*/
	get endAngle() : number {
		return (this.i.endAngle as number);
	}
	/**
	 * Gets the fill color of the slice.
	*/
	get fill() : string {
		return brushToString(this.i.fill);
	}
	/**
	 * Gets the outline color of the slice.
	*/
	get outline() : string {
		return brushToString(this.i.outline);
	}
}
