import { NumericScaler } from "./NumericScaler";
import { NumericAxisBase } from "./NumericAxisBase";
import { AutoRangeCalculator } from "./AutoRangeCalculator";
import { Base, Type, markType } from "igniteui-core/type";

/**
 * @hidden 
 */
export abstract class LinearScaler extends NumericScaler {
	static $t: Type = markType(LinearScaler, 'LinearScaler', (<any>NumericScaler).$);
	t(a: NumericAxisBase, b: number, c: number, d: number, e: number): { p3: number; p4: number; } {
		let f: number;
		let g: number;
		let h = AutoRangeCalculator.a(a, b, c, false, -1, f, g);
		f = h.p5;
		g = h.p6;
		d = f;
		e = g;
		return {
			p3: d,
			p4: e

		};
	}
}


