import { IgcAnnotationLayerProxyModule } from './igc-annotation-layer-proxy-module';

import { IgcFinalValueLayerComponent } from './igc-final-value-layer-component';
import { FinalValueLayer } from './FinalValueLayer';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcFinalValueLayerModule {
    public static register(): void {
IgcAnnotationLayerProxyModule.register();
        IgcFinalValueLayerComponent.register();
        TypeRegistrar.registerCons("IgcFinalValueLayerComponent", IgcFinalValueLayerComponent);
        TypeRegistrar.register("FinalValueLayer", (<any>FinalValueLayer).$type);
    }
}
