import { IgPoint } from 'igniteui-core/IgPoint'
import { IgDataTemplate } from 'igniteui-core/IgDataTemplate'
import { IgcHTMLElement } from 'igniteui-core/igc-html-element'
import { IgcSeriesComponent } from "./igc-series-component";
import { CalloutLabelUpdatingEventArgs as CalloutLabelUpdatingEventArgs_internal } from "./CalloutLabelUpdatingEventArgs";

/**
 * Represents event arguments for updating label of callout layer
*/
export class IgcCalloutLabelUpdatingEventArgs
{

protected createImplementation() : CalloutLabelUpdatingEventArgs_internal
{
	return new CalloutLabelUpdatingEventArgs_internal();
}
	protected _implementation: any;
	                            /**
	                             * @hidden 
	                             */
	public get i() : CalloutLabelUpdatingEventArgs_internal {
		return this._implementation;
	}
	private onImplementationCreated() {
		
	}
	constructor() {
	this._implementation = this.createImplementation();
	(<any>this._implementation).externalObject = this;
	this.onImplementationCreated();
	                                if ((this as any)._initializeAdapters) {
	                                    (this as any)._initializeAdapters();
	                                }
	
	}
	protected _provideImplementation(i: any) {
	    this._implementation = i;
	    (<any>this._implementation).externalObject = this;
	this.onImplementationCreated();
	                                if ((this as any)._initializeAdapters) {
	                                    (this as any)._initializeAdapters();
	                                }
	
	}
	/**
	 * Gets data X-value associated with callout layer
	*/
	get xValue() : any {
		return this.i.d as any;
	}
	set xValue(v: any) {
	                                        this.i.d = v;
	}
	/**
	 * Gets data Y-value associated with callout layer
	*/
	get yValue() : any {
		return this.i.e as any;
	}
	set yValue(v: any) {
	                                        this.i.e = v;
	}
	/**
	 * Gets data item associated with callout layer
	*/
	get item() : any {
		return this.i.item as any;
	}
	set item(v: any) {
	                                        this.i.item = v;
	}
	/**
	 * Gets series associated with callout item, if available
	*/
	get series() : IgcSeriesComponent {
	                                        const r = this.i.a;
	                                        if (r == null) {
	                                            return null;
	                                        }
	                                        
	                                        if (!(r as any).externalObject) {
	                                            let e = IgcSeriesComponent._createFromInternal(r);
	                                            if (e) {
	                                                (e as any)._implementation = r;
	                                            }
	                                            (r as any).externalObject = e;
	                                        }
		return (r as any).externalObject;
	}
	set series(v: IgcSeriesComponent) {
		v == null ? this.i.a = null : this.i.a = v.i;
	}
	/**
	 * Gets series name associated with callout item, if available
	*/
	get seriesName() : string {
		return (this.i.f as string);
	}
	set seriesName(v: string) {
		this.i.f = v;
	}
	/**
	 * Gets or sets label displayed by callout layer
	*/
	get label() : any {
		return this.i.c as any;
	}
	set label(v: any) {
	                                        this.i.c = v;
	}
}
