import { IgcAnnotationLayerProxyModule } from './igc-annotation-layer-proxy-module';

import { IgcUserAnnotationToolTipLayerComponent } from './igc-user-annotation-tool-tip-layer-component';
import { UserAnnotationToolTipLayer } from './UserAnnotationToolTipLayer';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcUserAnnotationToolTipLayerModule {
    public static register(): void {
IgcAnnotationLayerProxyModule.register();
        IgcUserAnnotationToolTipLayerComponent.register();
        TypeRegistrar.registerCons("IgcUserAnnotationToolTipLayerComponent", IgcUserAnnotationToolTipLayerComponent);
        TypeRegistrar.register("UserAnnotationToolTipLayer", (<any>UserAnnotationToolTipLayer).$type);
    }
}
