import { IgcDataChartToolbarIconsModule } from './igc-data-chart-toolbar-icons-module';
import { IgcDataChartAnnotationModule } from './igc-data-chart-annotation-module';
import { IgcAnnotationLayerProxyModule } from './igc-annotation-layer-proxy-module';
import { IgcDataChartCategoryTrendLineModule } from './igc-data-chart-category-trend-line-module';
import { IgcDataChartInteractivityModule } from './igc-data-chart-interactivity-module';
import { IgcCalloutLayerModule } from './igc-callout-layer-module';
import { IgcValueLayerModule } from './igc-value-layer-module';
import { IgcCrosshairLayerModule } from './igc-crosshair-layer-module';
import { DataChartToolbarFactoryManager } from './DataChartToolbarFactoryManager';
import { TypeRegistrar } from 'igniteui-core/type';


export class IgcDataChartToolbarModule {
    public static register() {
                IgcDataChartToolbarIconsModule.register();
        IgcDataChartAnnotationModule.register();
        IgcAnnotationLayerProxyModule.register();
        IgcDataChartCategoryTrendLineModule.register();
        IgcDataChartInteractivityModule.register();
        IgcCalloutLayerModule.register();
        IgcValueLayerModule.register();
        IgcCrosshairLayerModule.register();
        TypeRegistrar.register('DataChartToolbarFactoryManager', (DataChartToolbarFactoryManager as any).$type);
DataChartToolbarFactoryManager.register();

    }
}