import { IgcValueOverlayComponent } from './igc-value-overlay-component';
import { ValueOverlay } from './ValueOverlay';
import { TypeRegistrar } from 'igniteui-core/type';

export class IgcValueOverlayModule {
    public static register(): void {
        IgcValueOverlayComponent.register();
        TypeRegistrar.registerCons("IgcValueOverlayComponent", IgcValueOverlayComponent);
        TypeRegistrar.register("ValueOverlay", (<any>ValueOverlay).$type);
    }
}
